INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l01',1,1,'Excuse me, is this your phone?','打扰一下，这是你的手机吗？','Is this...? 一般疑问句 · this · my/your · Excuse me','西雅图一家咖啡店','{"q":"Whose phone is it?","options":["选项：","Tyler''s","Emma''s","The waiter''s"],"answer_index":2}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l02',1,2,'Here''s my ticket','给您我的取车票','Here''s... / Here are... · 祈使句请求 · my/your + 名词 · I''m sorry（道歉）','酒店门口代客泊车（valet parking）','{"q":"What color is David''s car?","options":["Gray","Blue","Black"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l03',1,3,'This is my friend Diego','这是我的朋友迭戈','冠词 a/an · 国籍表达 · This is + 人（介绍） · He''s/She''s','社区街区派对（block party）','{"q":"What is Diego''s job?","options":["A teacher","An engineer","A nurse"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l04',1,4,'What''s your job?','你是做什么工作的？','Are you...? 问答 · What''s your job? · a/an + 职业 · 国籍问答','社区大学晚间英语班第一天','{"q":"What is Sofia''s job?","options":["A nurse","An electrician","A teacher"],"answer_index":0}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l05',1,5,'How are you today?','你今天好吗？','How are you? / How''s...? 问答 · 形容词作表语 · 美式寒暄告别语','清晨遛狗偶遇邻居','{"q":"How is Carlos''s puppy?","options":["Sick","Happy","Tired"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l06',1,6,'Whose mug is this?','这是谁的马克杯？','Whose...? · 名词所有格 ''s · his/her · that','办公室茶水间认领马克杯','{"q":"Whose mug is it?","options":["Amanda''s","Tina''s","Chris''s"],"answer_index":2}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l07',2,7,'What color is your favorite?','你最喜欢什么颜色？','What color...? 问答 · 颜色形容词作定语（a green T-shirt） · What size...?','商场买 T 恤','{"q":"What is Lily''s favorite color?","options":["Blue","Green","Orange"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l08',2,8,'Are these your boxes?','这些是你的箱子吗？','名词复数（-s / -es） · these/those · Are these...? — Yes, they are. · they','搬家日，朋友帮忙核对物品','{"q":"Whose chairs are those?","options":["Sara''s","Emma''s","Jake''s"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l09',2,9,'These are my cousins','这些是我的表亲们','This is / These are + 人（介绍单复数） · we/they + are · 复数职业 · you guys','感恩节家庭聚餐','{"q":"What is Aunt Carol''s job?","options":["A cook","A doctor","A teacher"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l10',2,10,'What''s the matter?','你怎么了？','What''s the matter? 问答 · be + 状态形容词（tired/thirsty/hungry） · 程度词 so/really · Me too','徒步之后的加油站便利店','{"q":"How does Zoe feel?","options":["Happy","Tired and thirsty","Hungry only"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l11',2,11,'Which one?','哪一本？','Which...? 问句 · 替代词 one · this one / that one','公共图书馆找书','{"q":"What color is the book?","options":["Red","Blue","Green"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l12',2,12,'Which ones?','哪几副？','Which ones? 复数替代 · these/those + 形容词 + ones · 介词 on/in · 宾语代词 them 初步','眼镜店挑太阳镜','{"q":"Which sunglasses are on sale?","options":["The black ones","The brown ones","The blue ones"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l13',3,13,'Is there a pan here?','这里有平底锅吗？','There is... / Is there...? 问答 · 方位介词 in / on / under · There it is.','新公寓厨房，朋友帮忙做塔可','{"q":"Where is the salt?","options":["On the counter","In the cabinet","Under the coffee maker"],"answer_index":2}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l14',3,14,'Are there any old bikes?','有旧自行车吗？','There are... / Are there...? 问答 · some / any · 介词 behind','收拾车库，准备车库旧物出售','{"q":"Where are the bikes?","options":["On the shelf","Behind the boxes","Under the table"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l15',3,15,'Come in!','快请进！','祈使句（Come in / Sit down / Have some... / Try...） · must + 动词原形 · please','招待来家做客的朋友','{"q":"What is fresh?","options":["The cookies","The lemonade","The brownies"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l16',3,16,'What are you doing?','你在做什么？','现在进行时（单数）be + V-ing · What are you doing? 问答 · -ing 拼写规则','和奶奶视频通话','{"q":"What is Dad doing?","options":["Making dinner","Watching the game","Sleeping"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l17',3,17,'What''s happening at the park?','公园里在发生什么？','现在进行时（复数）They are + V-ing · What''s the weather like? 天气问答 · What''s happening?','周六早晨的公园（电话邀约）','{"q":"What''s the weather like?","options":["Rainy","Sunny and warm","Cloudy"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l18',3,18,'Welcome to Main Street','欢迎来到主街','there be + 现在进行时综合运用 · 物主代词 their · 地点介词综合（near / next to / behind / over there）','带表哥逛小镇主街与农夫集市','{"q":"What day is the farmers market?","options":["Saturday","Sunday","Monday"],"answer_index":0}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l19',4,19,'We''re going to have a BBQ!','我们要办烧烤啦！','be going to + 动词原形（计划打算） · Are you going to...? · It''s going to be...','邀请朋友参加周末后院烧烤','{"q":"What is Lisa going to make?","options":["Burgers","Potato salad","Brownies"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l20',4,20,'Don''t drop it!','别摔了！','否定祈使句 Don''t + 动词原形 · 祈使句扩展（Hurry / Move / Turn off） · 进行时复习','给妈妈布置生日惊喜派对','{"q":"What is Alex carrying?","options":["The banner","The balloons","The cake"],"answer_index":2}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l21',4,21,'Is there any juice?','还有果汁吗？','可数 vs 不可数名词 · 不可数名词 + some/any（There''s some milk / Is there any juice?） · a lot of','查冰箱列购物清单','{"q":"Is there any juice in the fridge?","options":["Yes, there is.","No, there isn''t.","We don''t know."],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l22',4,22,'Can you play the drums?','你会打鼓吗？','can / can''t + 动词原形（能力） · Can you...? 问答 · play the + 乐器','车库乐队招新','{"q":"Can Chloe play the guitar?","options":["Yes, she can.","No, she can''t.","We don''t know."],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l23',4,23,'Can you help me?','能帮我个忙吗？','Can you...?（礼貌请求） · 宾语代词全表（me/him/her/it/us/them） · Give it to...','办公室请同事帮忙','{"q":"Who is the box for?","options":["Sam","Kim","Dana"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l24',4,24,'Do you like sweet drinks?','你喜欢甜的饮品吗？','一般现在时 like/want（首次引入 do 助动词） · Do you...? — Yes, I do. / No, I don''t. · don''t + 动词原形 · A or B? 选择问句','咖啡店点单','{"q":"Rosa''s latte—hot or iced?","options":["Hot","Iced","Warm"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l25',5,25,'Let''s order pizza!','咱们点披萨吧！','like / love / don''t like（好恶程度） · not ... at all · Let''s + 动词原形 · What do you like?','室友商量披萨配料','{"q":"Emily says \"I don''t like ___ at all.\"","options":["Olives","Mushrooms","Pepperoni"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l26',5,26,'I usually get up at six','我通常六点起床','频度副词 always / usually / sometimes / never 及位置 · every + 时间 · 一般现在时表习惯','同事聊晨间习惯','{"q":"Ken usually gets up at ___.","options":["Five","Six","Seven"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l27',5,27,'Does he cook?','他会做饭吗？','第三人称单数动词 -s / -es · have → has · Does he/she...? — Yes, he does. · doesn''t + 动词原形','聊新室友','{"q":"Marco works at ___.","options":["A coffee shop","An animal hospital","A middle school"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l28',5,28,'The Carter family','卡特一家','三单综合运用 · 复数主语不加 -s 对照 · do homework · 时间表达（at night / in the morning / on Fridays）','一个美国家庭的一天（本课程首篇叙述体课文）','{"q":"What is Mr. Carter''s job?","options":["A teacher","A firefighter","A cashier"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l29',5,29,'Today is different','今天不一样','一般现在时（习惯） vs 现在进行时（此刻/这阵子）对比 · 信号词判断 · I usually..., but today I''m...','同事发现对方一反常态','{"q":"What is Molly drinking today?","options":["Coffee","Green tea","Soda"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l30',5,30,'Is that all?','就这些吗？','量词结构 a bag/box/bottle of · 结账三连（Is that all? / Anything else? / That''s it.） · Paper or plastic? · 价格口语读法','超市收银台结账','{"q":"Grace wants a bag of ___.","options":["Apples","Bananas","Cereal"],"answer_index":0}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l31',6,31,'I have a bad cold','我得了重感冒','have + 病症（a cold / a fever / a sore throat） · I don''t feel well. · Do you have...?','打电话向老板请病假','{"q":"What does Kayla have?","options":["A fever only","A bad cold","A headache"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l32',6,32,'You must rest','你必须休息','must（必须，医嘱/规定） · mustn''t（禁止） · must vs mustn''t 对照','诊所看医生（承接 L31 的 Kayla）','{"q":"How many days must Kayla rest?","options":["Two","Three","Five"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l33',6,33,'You don''t need to worry','你不必担心','need to / don''t need to（不必） · Do I need to...? · 情态三分小结（must / mustn''t / don''t need to）','青少年和爸爸谈周六外出条件','{"q":"What does Hailey need to clean?","options":["The kitchen","Her room","The garage"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l34',6,34,'How was your weekend?','你周末过得怎么样？','was / were（be 的过去式）陈述与疑问 · wasn''t / weren''t · 过去时间状语（on Saturday / all day / all night）','周一茶水间聊周末','{"q":"Where was Nicole on Saturday?","options":["At a wedding","At the beach","At home"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l35',6,35,'There was a huge Ferris wheel!','那儿有个巨大的摩天轮！','There was / There were（过去有） · Was there...? 问答 · 过去时间状语扩展（last summer / last year）','父女翻照片回忆去年的县集市','{"q":"What was huge at the fair?","options":["The pony","The Ferris wheel","The pie"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l36',6,36,'What happened?','发生什么事了？','规则动词过去式 -ed（构成三规则） · -ed 三种读音 · 叙事连接词 First / So / Then','向朋友吐槽昨天糟糕的一天','{"q":"Max spilled ___ on his laptop.","options":["Water","Coffee","Juice"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l37',7,37,'We drove to the Grand Canyon!','我们开车去了大峡谷！','不规则动词过去式第一批（went / took / drove / saw / ate / had） · 过去叙事串联','公路旅行归来分享','{"q":"Derek drove to ___.","options":["Miami","The Grand Canyon","The beach"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l38',7,38,'They''re too small','太小了','不规则过去式第二批（bought / wore / got / paid） · too + 形容词（过度） · not too...','网购球鞋到店退换','{"q":"Tessa''s sneakers are too ___.","options":["Big","Small","Old"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l39',7,39,'Did you call a mechanic?','你叫修车师傅了吗？','Did you...? — Yes, I did. / No, I didn''t. · didn''t + 动词原形 · 疑问中动词回原形','给牙医诊所打电话改约','{"q":"Why did Victor miss his appointment?","options":["His car didn''t start","He was sick","He forgot"],"answer_index":0}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l40',7,40,'How many burgers do we need?','我们需要多少个汉堡？','have to（不得不，客观必须） · Do we have to...? · How many + 可数复数 · How much + 不可数 / 问价格','仓储超市为派对采购','{"q":"How many burgers do they need?","options":["Twenty","Forty","Sixty"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l41',7,41,'Who won?','谁赢了？','过去式综合运用（规则 + 不规则混合叙事） · win → won · did 特殊疑问复现 · too much','感恩节次日复盘（L9 的 Mia/Noah/Grandpa Joe 回归）','{"q":"What did Mia make?","options":["The turkey","The mac and cheese","The casserole"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l42',7,42,'Last year, right now, tomorrow','去年、此刻、明天','过去 / 现在进行 / 将来打算三时态对照 · 时间状语对号入座 · swim→swam · forget→forgot','假期出发前的办公室对话（L36 的 Ivy/Max 回归）','{"q":"Where is Ivy going to fly?","options":["Dallas","Miami","Austin"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l43',8,43,'Have you ever been to Yellowstone?','你去过黄石公园吗？','现在完成时 have/has been to（经历） · Have you ever...? · ever / never · 过去分词初识（been / seen）','国家公园刮刮地图打卡清单','{"q":"Has Faith been to Yellowstone?","options":["Yes, twice","No, never","Only once"],"answer_index":0}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l44',8,44,'Someone has just hit my car!','有人刚剐了我的车！','现在完成时 just（刚刚） · yet（疑问"了吗"/否定"还没"） · 过去分词扩展（hit / found / taken / left / seen）','停车场剐蹭，打电话给保险公司（L39 的 Victor 回归）','{"q":"What has the other driver left?","options":["A phone","A note","A card"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l45',8,45,'It''s been forever!','好久不见啦！','现在完成时 + for（时间段）/ since（时间点） · How long...? · 持续到现在的状态','咖啡店偶遇十二年未见的高中老友','{"q":"How long has Wendy lived in Denver?","options":["Two years","Five years","Twelve years"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l46',8,46,'When did they sell it?','他们什么时候卖的？','现在完成时 vs 一般过去时对比（核心课） · 具体过去时间必用过去式 · sold / met 分词','邻居卖房、新住户搬来（L5 的 Carlos/Megan 回归）','{"q":"When did the Johnsons sell their house?","options":["Last Tuesday","Yesterday","This morning"],"answer_index":0}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l47',8,47,'He''ll fly to Tokyo next week','他下周要飞东京','will + 动词原形（将来） · 缩写 ''ll / won''t · Will...? 问答 · will vs be going to','聊新邻居是飞行员（承接 L46，Carlos/Megan 三连）','{"q":"What is Jonas''s job?","options":["A mechanic","A pilot","A firefighter"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l48',8,48,'When will it leave?','几点起飞？','will + 时刻（时刻表将来） · When will...? 问询 · 指路用语（go straight / past / on the left）','机场航班延误问询（L42 的 Ivy 在机场）','{"q":"When will the flight leave?","options":["At 3:15","At 3:45","At 7:30"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l49',9,49,'Is this yours?','这是你的吗？','名词性物主代词（mine / yours / his / hers / ours / theirs） · 与形容词性物主代词对照','健身房前台失物招领','{"q":"What does Paul''s bottle look like?","options":["Blue with a logo","Black with a sticker","White and small"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l50',9,50,'Don''t push yourself','别硬撑','反身代词全表（myself / yourself / himself...） · hurt oneself · by oneself · 固定表达（Help yourself / Take care of yourself）','篮球场边，朋友扭伤脚踝','{"q":"What hurts?","options":["Andre''s hand","Andre''s ankle","Andre''s head"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l51',9,51,'I got in!','我被录取了！','just / already / yet 三兄弟综合 · already 位置（have already + 分词） · know → knew','大学录取邮件揭晓时刻（L33 的 Hailey 长大了）','{"q":"Did Hailey get in?","options":["Yes, she got in!","No, she didn''t","We don''t know"],"answer_index":0}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l52',9,52,'You''ve got this!','你可以的！','too + 形容词 + for 人 / to 动词 · enough 两个位置（形容词后 / 名词前） · enough for','期末考前夜的图书馆','{"q":"When is the final?","options":["At 9 a.m.","At 2 p.m.","At midnight"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l53',9,53,'You write well!','你写得真好！','形容词 → 副词（-ly） · 形容词修饰名词 vs 副词修饰动词 · 特殊：hard / well · 陷阱：hardly','大学写作课同学互评','{"q":"What should \"He runs quick\" be?","options":["He runs quicker","He runs quickly","He quickly runs good"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l54',9,54,'Do you have a bigger size?','有大一号的吗？','比较级 -er + than · 构成规则（双写 / 直接加） · 不规则 good → better · 程度修饰 way / much','服装店买牛仔裤（L38 的 Tessa 与店员 Ray 重逢）','{"q":"The softer jeans are also ___.","options":["Tighter","Cheaper","Bigger"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l55',10,55,'More romantic or more famous?','更浪漫还是更有名？','多音节形容词比较级 more + adj · -er / more 判断规则 · way/much + more','结婚十周年选餐厅','{"q":"Which restaurant do they pick?","options":["The Harbor House","Bella Roma","Neither"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l56',10,56,'The cheapest car on the lot','全场最便宜的车','最高级 the + -est / the most · 不规则 best / worst · 范围搭配（in town / on the lot）','车行选车试驾','{"q":"The cheapest car costs ___.","options":["Nine thousand","Twelve thousand","Five thousand"],"answer_index":0}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l57',10,57,'Do you have any quarters?','你有 25 美分硬币吗？','some / any 代词化（后不接名词） · none · if you have any · 美国硬币体系','街边停车咪表找零钱','{"q":"What does the meter take?","options":["Bills","Quarters","Dimes"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l58',10,58,'Somebody is at the door!','有人在敲门！','somebody / anybody / nobody / everybody 四兄弟 · 单数动词一致 · 分工同 some/any','万圣节夜，糖果失踪之谜','{"q":"Who took the candy?","options":["A kid","A dog","Nobody"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l59',10,59,'I was riding my bike when...','我正骑着车，突然……','过去进行时 was/were + V-ing · when + 一般过去式（打断） · while + 过去进行（同时） · Were you...?','办公室周一，胳膊打石膏的故事（L29 的 Molly/Raj 回归）','{"q":"What was Raj doing when the squirrel appeared?","options":["Running","Riding his bike","Driving"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l60',10,60,'Raccoon Palace','浣熊行宫','过去进行时综合叙事（背景动作 + 突发事件） · while 复现 · hear → heard · 副词体系综合运用','露营夜的怪声之谜（本课程第二篇叙述体，L50 的 Kyle/Andre 回归）','{"q":"What was making the sound?","options":["A bear","A raccoon","The wind"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l61',11,61,'A detective who never asks questions','一个从不提问的侦探','定语从句 who（修饰人） · who 作从句主语后接动词 · 从句动词单复数一致','独立书店请店员荐书','{"q":"What does Emma''s brother love?","options":["Cookbooks","Mysteries","History books"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l62',11,62,'A market that sells everything','什么都卖的市集','定语从句 which / that（修饰物） · who（人） vs which/that（物）对照 · that 从句含完整主谓','周末跳蚤市场淘货','{"q":"What does Sara want for her desk?","options":["A record","A lamp","A box"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l63',11,63,'You have to mow your lawn','你得修剪草坪','have to 深化（三态 + 三单 has to） · don''t have to（不必） vs can''t（不可以） · every two weeks / by...','新邻居收到 HOA 信件，请教社区规定（L47 的 Jonas 请教 Carlos）','{"q":"How often does Jonas have to mow the lawn?","options":["Every week","Every two weeks","Every month"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l64',11,64,'He must be a programmer','他一定是个程序员','must be + 名词/形容词/V-ing（肯定推测"一定是"） · 推测 must vs 义务 must 辨析','咖啡店"人间观察"游戏（L24 的 Rosa + L13 的 Nina）','{"q":"What does the man in the suit keep doing?","options":["Drinking coffee","Checking his watch","Reading a book"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l65',11,65,'That can''t be right!','这不可能对！','can''t be（否定推测"不可能是"） · must be ↔ can''t be 对照 · There must be a mistake. · catch → caught','公路超速被拦（Victor 倒霉三部曲终章）','{"q":"What color was the fast sports car?","options":["Black","Red","Blue"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l66',11,66,'It might rain','可能会下雨','may / might + 动词原形（不确定推测） · may not / might not · 推测三级总表（must be > may/might > can''t be）','天气不定的野餐计划（L45 的 Wendy/Dana 续集）','{"q":"What might Wendy''s sister bring?","options":["Cookies","Lemon bars","A blanket"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l67',12,67,'He said that twenty years was enough','他说二十年够了','say → said (that) + 从句 · that 可省略 · 转述人称转换 · 时态后移初识（is → was）','聊传奇球星退役新闻','{"q":"What might Marcus Cole open?","options":["A bookstore","A pizza place","A gym"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l68',12,68,'Who told you?','谁跟你说的？','tell + 人 + (that) · say vs tell 铁律（say 不接人 / tell 必接人） · told everybody','小镇消息链（Maplewood 全联动：书店搬家 + 派对改址）','{"q":"Where is the bookstore moving?","options":["The river","Main Street","The mall"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l69',12,69,'If we win, we''ll split it!','要是中了，咱们平分！','第一条件句 If + 一般现在时, will + 原形 · if 从句不用 will · What will you do if...?','加油站买彩票的白日梦（L10 的 Zoe/Ryan 回归）','{"q":"What will they do if they win?","options":["Buy a car","Split it fifty-fifty","Keep it secret"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l70',12,70,'Sorry, wrong number!','抱歉，打错了！','电话套语包（This is... / Wrong number / May I ask...?） · I''d like + 名词 · tell...that 转述落地 · ago','想订披萨却打到了牙科诊所（L39 的 Gloria 接到 L27 的 Bella）','{"q":"Where did Bella want to call?","options":["A dental office","Tony''s Pizza","A bookstore"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l71',12,71,'I had never been on a plane','我之前从没坐过飞机','过去完成时 had + 过去分词（"过去的过去"） · had never ... before · By the time..., had... · fly → flown','第一次坐飞机去大学报到（Hailey 成长线终章）','{"q":"Before today, Hailey had never been on a ___.","options":["Train","Plane","Boat"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_lessons (id,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question) VALUES ('am1_l72',12,72,'Maplewood had never looked better','枫木镇从没这么美过','全书综合复习——八大时态 + 推测 + 定语从句 + 转述 + 条件句同框 · 第三篇叙述体（大团圆结局）','Maplewood 新河滨步道启用日，全员社区派对','{"q":"What did Maplewood open?","options":["A new bookstore","A new river trail","A new school"],"answer_index":1}'::jsonb) ON CONFLICT (id) DO UPDATE SET title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l01',1,'Tyler','Excuse me, ma''am.','泰勒：打扰一下，女士。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l01',2,'Emma','Yes?','艾玛：什么事？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l01',3,'Tyler','Is this your phone?','泰勒：这是你的手机吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l01',4,'Tyler','It was on the chair.','泰勒：它刚才在椅子上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l01',5,'Emma','Oh! Yes, it is.','艾玛：哦！是的，是我的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l01',6,'Emma','It''s my phone.','艾玛：这是我的手机。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l01',7,'Tyler','Here you go.','泰勒：给你。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l01',8,'Emma','Thank you so much!','艾玛：太感谢了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l01',9,'Emma','You''re a lifesaver.','艾玛：你真是帮了大忙。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l01',10,'Tyler','No problem. Have a good one!','泰勒：不客气。祝你愉快！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l02',1,'Marcus','Good evening, sir. Welcome to the Grandview Hotel.','马库斯：晚上好，先生。欢迎光临格兰景酒店。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l02',2,'David','Hi. Here''s my ticket.','大卫：你好。给您我的取车票。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l02',3,'Marcus','Thank you. One moment, please.','马库斯：谢谢。请稍等。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l02',4,'Marcus','Is this your car? The gray SUV?','马库斯：这是您的车吗？那辆灰色 SUV？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l02',5,'David','No, it isn''t. My car is the blue one.','大卫：不，不是。我的车是蓝色那辆。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l02',6,'Marcus','Oh, I''m sorry, sir.','马库斯：哦，抱歉，先生。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l02',7,'Marcus','Here are your keys.','马库斯：给您钥匙。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l02',8,'David','Thanks. And this is your tip.','大卫：谢谢。这是给你的小费。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l02',9,'Marcus','Thank you, sir. Have a great night!','马库斯：谢谢您，先生。祝您夜晚愉快！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l03',1,'Rachel','Hi, Ben! This is my friend Diego.','瑞秋：嗨，本！这是我的朋友迭戈。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l03',2,'Ben','Nice to meet you, Diego.','本：很高兴认识你，迭戈。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l03',3,'Diego','Nice to meet you too.','迭戈：我也很高兴认识你。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l03',4,'Ben','Are you new to the neighborhood?','本：你是新搬来这个社区的吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l03',5,'Diego','Yes, I am. I''m from Mexico. I''m Mexican.','迭戈：是的。我来自墨西哥，我是墨西哥人。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l03',6,'Rachel','Diego is an engineer.','瑞秋：迭戈是一名工程师。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l03',7,'Ben','Oh, nice! I''m a teacher at the middle school.','本：真棒！我是中学的一名老师。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l03',8,'Diego','This is a great party.','迭戈：这个派对真不错。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l03',9,'Ben','Welcome to the block, Diego!','本：欢迎来到我们街区，迭戈！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l04',1,'Kevin','Hi, I''m Kevin. Are you new here?','凯文：嗨，我是凯文。你是新来的吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l04',2,'Sofia','Yes, I am. My name''s Sofia.','索菲亚：是的。我叫索菲亚。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l04',3,'Kevin','Are you American?','凯文：你是美国人吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l04',4,'Sofia','No, I''m not. I''m Brazilian.','索菲亚：不，我是巴西人。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l04',5,'Sofia','Are you a student here too?','索菲亚：你也是这里的学生吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l04',6,'Kevin','Yes, I am.','凯文：是的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l04',7,'Kevin','What''s your job, Sofia?','凯文：索菲亚，你是做什么工作的？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l04',8,'Sofia','I''m a nurse. What about you?','索菲亚：我是护士。你呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l04',9,'Kevin','I''m an electrician.','凯文：我是电工。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l04',10,'Sofia','Cool! Nice to meet you, Kevin.','索菲亚：真棒！很高兴认识你，凯文。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l05',1,'Megan','Good morning, Carlos! How are you today?','梅根：早上好，卡洛斯！你今天好吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l05',2,'Carlos','I''m great, thanks. And you?','卡洛斯：我很好，谢谢。你呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l05',3,'Megan','I''m pretty good.','梅根：我挺好的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l05',4,'Megan','How''s your wife?','梅根：你妻子好吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l05',5,'Carlos','She''s fine, thank you.','卡洛斯：她很好，谢谢。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l05',6,'Megan','And how''s your new puppy?','梅根：你家新来的小狗怎么样？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l05',7,'Carlos','He''s a handful! But he''s happy.','卡洛斯：他可真难带！不过他很开心。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l05',8,'Megan','Ha! See you later, Carlos.','梅根：哈哈！回头见，卡洛斯。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l05',9,'Carlos','Take care, Megan!','卡洛斯：保重，梅根！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l06',1,'Tina','Whose coffee mug is this? It was in the sink.','蒂娜：这是谁的咖啡杯？刚才在水槽里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l06',2,'Jake','Is it Amanda''s mug?','杰克：是阿曼达的杯子吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l06',3,'Tina','No, her mug is pink. This one is black.','蒂娜：不是，她的杯子是粉色的。这只是黑色的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l06',4,'Jake','Maybe it''s Chris''s mug. His mug is black.','杰克：也许是克里斯的。他的杯子是黑色的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l06',5,'Tina','Chris! Is this your mug?','蒂娜：克里斯！这是你的杯子吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l06',6,'Chris','Oh, yes! That''s my mug. Thanks, Tina!','克里斯：哦，是的！那是我的杯子。谢谢，蒂娜！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l06',7,'Tina','No problem. Please wash it, okay?','蒂娜：不客气。请把它洗了，好吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l06',8,'Chris','My bad. Sorry!','克里斯：我的错。抱歉！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l07',1,'Clerk','Hi! Can I help you?','店员：您好！需要帮忙吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l07',2,'Lily','Yes, please. I''m here for a T-shirt.','莉莉：是的，谢谢。我想买件 T 恤。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l07',3,'Clerk','Great! What color is your favorite?','店员：好嘞！你最喜欢什么颜色？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l07',4,'Lily','My favorite color is green.','莉莉：我最喜欢绿色。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l07',5,'Clerk','Here''s a green T-shirt. It''s very popular.','店员：给您看这件绿色 T 恤，非常受欢迎。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l07',6,'Lily','It''s cute! But it''s a small.','莉莉：真好看！可惜是小码。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l07',7,'Lily','What size is that one over there?','莉莉：那边那件是什么尺码？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l07',8,'Clerk','It''s a medium.','店员：是中码。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l07',9,'Lily','Perfect. And what color is that T-shirt?','莉莉：太好了。那件 T 恤是什么颜色？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l07',10,'Clerk','It''s orange. It''s on sale—only ten dollars.','店员：橙色的，正在打折——只要十美元。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l07',11,'Lily','Wow! The green T-shirt and the orange T-shirt, please.','莉莉：哇！绿色这件和橙色那件我都要了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l07',12,'Clerk','Sure! Here you go.','店员：没问题！给您。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l08',1,'Jake','Okay, Sara. Are these your boxes?','杰克：好了，萨拉。这些是你的箱子吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l08',2,'Sara','Yes, they are. They''re books.','萨拉：是的。里面都是书。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l08',3,'Jake','Wow, they''re heavy!','杰克：哇，好重！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l08',4,'Sara','Sorry! I''m a bookworm.','萨拉：抱歉！我是个书虫。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l08',5,'Jake','Ha! And are those your chairs?','杰克：哈哈！那些是你的椅子吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l08',6,'Sara','No, they aren''t. Those are Emma''s chairs.','萨拉：不是。那些是艾玛的椅子。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l08',7,'Jake','Got it. And this lamp?','杰克：明白。这盏台灯呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l08',8,'Sara','It''s my lamp. Careful—it''s new!','萨拉：是我的台灯。小心点——是新的！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l08',9,'Jake','No problem. The truck is full!','杰克：没问题。卡车装满啦！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l08',10,'Sara','Thanks, Jake. Pizza is on me!','萨拉：谢谢你，杰克。披萨我请客！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l09',1,'Mia','Welcome, Noah! Happy Thanksgiving!','米娅：欢迎，诺亚！感恩节快乐！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l09',2,'Noah','Happy Thanksgiving, Mia! Wow, your family is big!','诺亚：感恩节快乐，米娅！哇，你家人真多！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l09',3,'Mia','Ha! Come—this is my aunt Carol. She''s a doctor.','米娅：哈哈！来——这是我姑姑卡罗尔，她是医生。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l09',4,'Noah','Nice to meet you, Carol.','诺亚：很高兴认识您，卡罗尔。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l09',5,'Carol','Nice to meet you too, Noah.','卡罗尔：我也很高兴认识你，诺亚。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l09',6,'Mia','And these are my cousins, Ethan and Ava.','米娅：这些是我的表亲，伊森和艾娃。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l09',7,'Noah','Hi, guys! Are you students?','诺亚：嗨，你们好！你们是学生吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l09',8,'Ethan','Yes, we are. We''re in college.','伊森：是的，我们在上大学。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l09',9,'Mia','And this is my grandpa Joe. He''s a great cook.','米娅：这是我爷爷乔，他做饭一流。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l09',10,'Noah','Nice to meet you, sir. The turkey is amazing!','诺亚：很高兴认识您，先生。火鸡太好吃了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l09',11,'Grandpa','Thank you, Noah! Welcome to the family dinner.','爷爷：谢谢你，诺亚！欢迎来我们的家宴。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l09',12,'Noah','I''m happy to be here!','诺亚：能来我太开心了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l10',1,'Ryan','Hey, Zoe. What''s the matter?','瑞安：嘿，佐伊。你怎么了？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l10',2,'Zoe','I''m so tired. And I''m thirsty.','佐伊：我累坏了，还很渴。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l10',3,'Ryan','Me too. That trail is long!','瑞安：我也是。那条步道太长了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l10',4,'Zoe','Look, a gas station!','佐伊：看，加油站！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l10',5,'Ryan','Great. Water for you?','瑞安：太好了。给你买水？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l10',6,'Zoe','Yes, please. I''m really thirsty.','佐伊：好的，谢谢。我真的很渴。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l10',7,'Ryan','Two bottles of water, please.','瑞安：请拿两瓶水。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l10',8,'Clerk','Here you go. Anything else?','店员：给您。还要别的吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l10',9,'Ryan','Two snacks too. We''re hungry!','瑞安：再来两份零食。我们饿了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l10',10,'Clerk','Sure! Here they are.','店员：好嘞！都在这儿。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l11',1,'Emma','Excuse me. Is "The Lost Trail" here?','艾玛：打扰一下，《迷路的步道》这本书在吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l11',2,'Librarian','Yes, it is. It''s on that shelf.','图书管理员：在的，就在那个书架上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l11',3,'Emma','Hmm, which book is it?','艾玛：呃，是哪一本？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l11',4,'Librarian','The blue one, next to the lamp.','管理员：蓝色那本，台灯旁边。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l11',5,'Emma','This one?','艾玛：这本吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l11',6,'Librarian','No, not that one. The big blue one.','管理员：不，不是那本。大的蓝色那本。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l11',7,'Emma','Oh! This one. Got it.','艾玛：哦！这本。明白了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l11',8,'Librarian','That''s a great book. My favorite!','管理员：那本书特别好，我的最爱！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l11',9,'Emma','Awesome. Thank you so much!','艾玛：太棒了。非常感谢！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l11',10,'Librarian','You''re welcome. Enjoy!','管理员：不客气。阅读愉快！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l12',1,'Clerk','Welcome in! Are you here for glasses?','店员：欢迎光临！您是来配眼镜的吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l12',2,'Dan','Yes. Sunglasses, actually.','丹：是的。确切说是太阳镜。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l12',3,'Clerk','Great. The sunglasses are on the top shelf.','店员：好嘞。太阳镜都在最上层架子上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l12',4,'Dan','Which ones are popular?','丹：哪几副卖得好？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l12',5,'Clerk','These black ones. They''re new.','店员：这几副黑色的，是新款。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l12',6,'Dan','Hmm. And those brown ones? Are they new too?','丹：嗯。那几副棕色的呢？也是新款吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l12',7,'Clerk','No, they aren''t. But they''re on sale.','店员：不是。不过它们在打折。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l12',8,'Dan','Nice. Are small sizes in this drawer?','丹：不错。小号的在这个抽屉里吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l12',9,'Clerk','Yes, they are. Here—try them on!','店员：是的。来——试戴一下！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l12',10,'Dan','Wow, these are perfect. The brown ones, please!','丹：哇，太合适了。就要棕色这几副！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l12',11,'Clerk','Sure thing!','店员：没问题！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l13',1,'Owen','Nice kitchen, Nina!','欧文：厨房不错啊，妮娜！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l13',2,'Nina','Thanks! It''s small but cozy.','妮娜：谢谢！小是小，但很温馨。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l13',3,'Owen','Okay, taco night! Is there a pan here?','欧文：好嘞，塔可之夜！这儿有平底锅吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l13',4,'Nina','Yes, there is. It''s in that cabinet.','妮娜：有的，在那个柜子里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l13',5,'Owen','Got it. And the salt?','欧文：找到了。盐呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l13',6,'Nina','It''s on the counter, next to the stove.','妮娜：在台面上，炉灶旁边。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l13',7,'Owen','Hmm, it isn''t here.','欧文：呃，这儿没有啊。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l13',8,'Nina','Oops! Then it''s under the coffee maker. Sorry!','妮娜：哎呀！那就是在咖啡机下面。抱歉！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l13',9,'Owen','Ha! There it is.','欧文：哈！找到了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l13',10,'Nina','Great. Taco time!','妮娜：太好了。开做塔可！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l14',1,'Kate','Wow, this garage is a mess!','凯特：哇，这车库也太乱了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l14',2,'Ben','I know. Okay—garage sale time.','本：就是说啊。好——该办车库大甩卖了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l14',3,'Kate','Good idea! Are there any old bikes here?','凯特：好主意！这儿有旧自行车吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l14',4,'Ben','Yes, there are. There are two bikes behind the boxes.','本：有的。箱子后面有两辆。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l14',5,'Kate','Perfect. And there are some old games on that shelf.','凯特：太好了。那个架子上还有些旧桌游。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l14',6,'Ben','Are there any tools in this box?','本：这个箱子里有工具吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l14',7,'Kate','No, there aren''t. There are only books in it.','凯特：没有。里面只有书。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l14',8,'Ben','Hmm, there are some paintbrushes under the table too.','本：嗯，桌子下面还有些刷子。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l14',9,'Kate','Those are Dad''s. Not for sale!','凯特：那是爸爸的。不卖！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l14',10,'Ben','Ha! Got it.','本：哈哈！明白。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l15',1,'Priya','Leo! Come in, come in!','普丽娅：利奥！快请进！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l15',2,'Leo','Thanks, Priya. Wow, your place is nice!','利奥：谢谢，普丽娅。哇，你家真不错！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l15',3,'Priya','Sit down, please. Make yourself at home.','普丽娅：请坐，别拘束，就当自己家。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l15',4,'Leo','Thank you.','利奥：谢谢。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l15',5,'Priya','Have some lemonade. It''s fresh.','普丽娅：喝点柠檬水，刚做的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l15',6,'Leo','Mmm, it''s so good!','利奥：嗯，太好喝了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l15',7,'Priya','And try these cookies. But careful—they''re hot!','普丽娅：再尝尝这些曲奇。不过小心——烫！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l15',8,'Leo','Ha! Okay. Oh wow, they''re amazing.','利奥：哈哈！好。哇，太好吃了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l15',9,'Priya','You must try my brownies next time.','普丽娅：下次你一定要尝尝我的布朗尼。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l15',10,'Leo','It''s a deal!','利奥：一言为定！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l16',1,'Grandma','Hi, sweetie! What are you doing?','奶奶：嗨，宝贝！你在做什么呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l16',2,'Carmen','Hi, Grandma! I''m making dinner.','卡门：嗨，奶奶！我在做晚饭。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l16',3,'Grandma','Nice! Where''s your dad?','奶奶：真棒！你爸爸呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l16',4,'Carmen','He''s watching the game in the living room.','卡门：他在客厅看比赛。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l16',5,'Grandma','Of course he is! Ha! And your mom?','奶奶：他肯定在看！哈哈！你妈妈呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l16',6,'Carmen','She''s working in the garden.','卡门：她在花园里干活。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l16',7,'Grandma','And where''s Buster?','奶奶：巴斯特（狗）呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l16',8,'Carmen','He''s sleeping under the table. Wait—no! He''s eating my taco!','卡门：它在桌子下睡觉。等等——不对！它在吃我的塔可！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l16',9,'Grandma','Ha ha! Bad dog!','奶奶：哈哈！坏狗狗！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l16',10,'Carmen','Buster! Grandma, sorry—gotta go!','卡门：巴斯特！奶奶，抱歉——我得挂了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l16',11,'Grandma','Go, go! Love you, sweetie!','奶奶：去吧去吧！爱你，宝贝！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l17',1,'Tom','Jess! Come to Riverside Park. It''s a beautiful day!','汤姆：杰丝！快来河滨公园，今天天气太好了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l17',2,'Jess','Oh yeah? What''s the weather like?','杰丝：是吗？天气怎么样？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l17',3,'Tom','It''s sunny and warm. No clouds!','汤姆：晴朗又暖和，一朵云都没有！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l17',4,'Jess','Nice! What''s happening there?','杰丝：不错！那边有什么好玩的？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l17',5,'Tom','A lot! Some kids are flying kites.','汤姆：可多了！几个孩子在放风筝。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l17',6,'Tom','Two guys are playing guitar under a tree.','汤姆：两个小伙在树下弹吉他。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l17',7,'Jess','Fun! And the food trucks?','杰丝：有意思！餐车来了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l17',8,'Tom','They''re selling tacos and ice cream. People are waiting in line.','汤姆：他们在卖塔可和冰淇淋，大家排着队呢。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l17',9,'Jess','Say no more. I''m coming!','杰丝：别说了，我这就来！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l17',10,'Tom','Awesome. We''re sitting near the fountain.','汤姆：太好了。我们坐在喷泉附近。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l18',1,'Maya','Welcome to Maplewood! This is Main Street.','玛雅：欢迎来到枫木镇！这就是主街。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l18',2,'Sam','It''s so charming!','山姆：太有味道了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l18',3,'Maya','There''s a farmers market every Saturday. Look—it''s happening now!','玛雅：每周六都有农夫集市。看——现在正开着呢！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l18',4,'Sam','Cool! What are they selling?','山姆：酷！他们在卖什么？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l18',5,'Maya','Fresh corn, honey, flowers... And there are food stands over there.','玛雅：新鲜玉米、蜂蜜、鲜花……那边还有小吃摊。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l18',6,'Sam','Oh, a band is playing near the bookstore!','山姆：哦，书店附近有支乐队在演奏！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l18',7,'Maya','Yep. And there''s a coffee shop next to it. Their lattes are amazing.','玛雅：对。旁边还有家咖啡店，他们的拿铁一绝。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l18',8,'Sam','This town is awesome. Wait—is there an ice cream shop too?','山姆：这镇子太棒了。等等——有冰淇淋店吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l18',9,'Maya','Of course! It''s behind the market. Two brothers are running it.','玛雅：当然！就在集市后面，兄弟俩开的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l18',10,'Sam','Maplewood, I''m staying forever!','山姆：枫木镇，我不走了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l19',1,'Mark','Hey, Tina! Are you free this Saturday?','马克：嘿，蒂娜！这周六有空吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l19',2,'Tina','Yes, I am. Why?','蒂娜：有啊。怎么了？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l19',3,'Mark','We''re going to have a BBQ in our backyard!','马克：我们要在后院办烧烤！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l19',4,'Tina','Fun! What''s the plan?','蒂娜：好玩！都有什么安排？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l19',5,'Mark','I''m going to grill burgers and hot dogs.','马克：我要烤汉堡和热狗。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l19',6,'Mark','And Lisa is going to make her famous potato salad.','马克：丽莎要做她的招牌土豆沙拉。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l19',7,'Tina','Yum! What about drinks?','蒂娜：馋了！饮料呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l19',8,'Mark','We''re going to get lemonade and soda.','马克：我们会备柠檬水和汽水。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l19',9,'Tina','Perfect. I''m going to bring brownies!','蒂娜：完美。我要带布朗尼来！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l19',10,'Mark','Awesome! It''s going to be a great day.','马克：太棒了！那天肯定特别开心。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l19',11,'Tina','See you Saturday!','蒂娜：周六见！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l20',1,'Alex','Okay, Mom is coming at six. Hurry!','亚历克斯：好了，妈妈六点到。快点！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l20',2,'Ruby','I''m hanging the banner. How is it?','鲁比：我在挂横幅呢。怎么样？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l20',3,'Alex','Move it up a little... Perfect!','亚历克斯：往上挪一点……完美！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l20',4,'Ruby','What are you doing?','鲁比：你在干嘛？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l20',5,'Alex','I''m carrying the cake. It''s heavy!','亚历克斯：我在端蛋糕。好沉！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l20',6,'Ruby','Careful! Don''t drop it!','鲁比：小心！别摔了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l20',7,'Alex','Don''t worry!','亚历克斯：放心吧！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l20',8,'Ruby','And don''t touch the balloons—they''re ready.','鲁比：还有别碰气球——都摆好了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l20',9,'Alex','Got it. Wait—she''s here! Turn off the lights!','亚历克斯：明白。等等——她到了！快关灯！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l20',10,'Ruby','Shh! Don''t make a sound!','鲁比：嘘！别出声！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l20',11,'Mom','Hello...? Kids?','妈妈：有人吗……？孩子们？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l20',12,NULL,'ALEX & RUBY: SURPRISE! Happy birthday, Mom!','兄妹俩：惊喜！生日快乐，妈妈！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l21',1,'Amy','Nate, I''m making a shopping list. Check the fridge.','艾米：内特，我在列购物清单。你查下冰箱。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l21',2,'Nate','On it! Okay... there''s some milk.','内特：这就去！嗯……有一些牛奶。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l21',3,'Amy','Good. Is there any juice?','艾米：好。有果汁吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l21',4,'Nate','No, there isn''t. And there isn''t any cheese.','内特：没有。奶酪也没了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l21',5,'Amy','Okay—juice and cheese. What about bread?','艾米：好——记上果汁和奶酪。面包呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l21',6,'Nate','There''s some bread, but it''s old.','内特：有点面包，不过不新鲜了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l21',7,'Amy','Bread too, then. Any eggs?','艾米：那面包也记上。鸡蛋呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l21',8,'Nate','Yes, there are some eggs. Six.','内特：有的，还有六个。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l21',9,'Amy','And water?','艾米：水呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l21',10,'Nate','There''s a lot of water. We''re good!','内特：水很多。这个不缺！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l22',1,'Jordan','Hey! Are you here for the band?','乔丹：嘿！你是来应乐队的吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l22',2,'Chloe','Yes! I''m Chloe.','克洛伊：对！我叫克洛伊。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l22',3,'Jordan','Cool. Can you play the guitar?','乔丹：酷。你会弹吉他吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l22',4,'Chloe','No, I can''t. But I can play the drums!','克洛伊：不会。但我会打鼓！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l22',5,'Jordan','Really? Show us!','乔丹：真的？露一手！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l22',6,'Jordan','Wow! You can really play!','乔丹：哇！你是真会打！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l22',7,'Chloe','Thanks! I can sing a little too.','克洛伊：谢谢！我还会唱一点。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l22',8,'Jordan','Awesome. Mike can play bass, and I can play guitar.','乔丹：太棒了。迈克弹贝斯，我弹吉他。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l22',9,'Chloe','Nice! Can you guys practice on weekends?','克洛伊：不错！你们周末能排练吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l22',10,'Jordan','Sure. We can practice in my garage.','乔丹：当然。我们可以在我家车库排练。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l22',11,'Chloe','Then I''m in!','克洛伊：那算我一个！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l23',1,'Dana','Sam, are you busy? Can you help me?','达娜：山姆，你忙吗？能帮我个忙吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l23',2,'Sam','Sure! What''s up?','山姆：当然！什么事？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l23',3,'Dana','This report is due at three. Can you check it for me?','达娜：这份报告三点前要交。能帮我核一遍吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l23',4,'Sam','No problem. Give it to me.','山姆：没问题。给我吧。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l23',5,'Dana','Thanks! And these charts—can you print them?','达娜：谢了！还有这些图表——能帮我打印吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l23',6,'Sam','Sure thing. And this box?','山姆：没问题。这个箱子呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l23',7,'Dana','Oh, that''s for Kim. Can you give it to her?','达娜：哦，那是给金姆的。能帮我转交给她吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l23',8,'Sam','Got it. Anything else?','山姆：明白。还有别的吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l23',9,'Dana','No, that''s it. You''re the best! Coffee is on me!','达娜：没了，就这些。你太靠谱了！咖啡我请！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l23',10,'Sam','Ha! Deal.','山姆：哈！成交。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l24',1,'Barista','Hi! Welcome to Beantown. What can I get you?','店员：您好！欢迎来到豆子镇咖啡。您要点什么？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l24',2,'Rosa','Hmm. I want a latte, please.','罗莎：嗯……我要一杯拿铁。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l24',3,'Barista','Hot or iced?','店员：热的还是冰的？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l24',4,'Rosa','Iced, please. It''s so warm today.','罗莎：冰的。今天太热了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l24',5,'Barista','Do you want milk or oat milk?','店员：要牛奶还是燕麦奶？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l24',6,'Rosa','Oat milk. I like it a lot.','罗莎：燕麦奶。我特别喜欢。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l24',7,'Barista','Nice choice. Do you like sweet drinks?','店员：好选择。您喜欢甜口的吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l24',8,'Rosa','Not really. I don''t like sugar in my coffee.','罗莎：不太喜欢。我咖啡里不加糖。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l24',9,'Barista','Got it. One iced oat milk latte, no sugar.','店员：明白。一杯冰燕麦拿铁，不加糖。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l24',10,'Rosa','Perfect. Oh—and I want a cookie too!','罗莎：完美。哦——再来一块曲奇！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l24',11,'Barista','You got it!','店员：好嘞！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l25',1,'Josh','Let''s order pizza! What do you like?','乔什：咱们点披萨吧！你喜欢什么口味？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l25',2,'Emily','I love pepperoni. Do you like it?','艾米丽：我超爱意式辣香肠。你喜欢吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l25',3,'Josh','Yes, I do. But I really love mushrooms.','乔什：喜欢。不过我最爱的是蘑菇。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l25',4,'Emily','Ugh, mushrooms? I don''t like them at all!','艾米丽：呃，蘑菇？我一点都不喜欢！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l25',5,'Josh','Ha! Okay. What about olives?','乔什：哈哈！好吧。橄榄呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l25',6,'Emily','I like olives. And I love extra cheese!','艾米丽：橄榄可以。而且我爱加倍芝士！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l25',7,'Josh','Me too. So—pepperoni, olives, and extra cheese.','乔什：我也是。那就——辣香肠、橄榄、加倍芝士。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l25',8,'Emily','Perfect. Oh wait—do you like thin crust?','艾米丽：完美。等等——你喜欢薄底吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l25',9,'Josh','Yes! Thin crust is the way to go.','乔什：喜欢！薄底才是正解。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l25',10,'Emily','Great. I''m calling Tony''s now.','艾米丽：好。我这就给托尼披萨店打电话。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l25',11,'Josh','Tell them: no pineapple!','乔什：跟他们说：不要菠萝！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l26',1,'Lauren','Ken, you''re always early! What''s your secret?','劳伦：肯，你总是来这么早！有什么秘诀？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l26',2,'Ken','Ha! I usually get up at six.','肯：哈哈！我通常六点起床。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l26',3,'Lauren','Six?! I never get up at six.','劳伦：六点？！我从来没六点起过。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l26',4,'Ken','I run every morning. Then I make coffee.','肯：我每天早晨跑步，然后煮咖啡。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l26',5,'Lauren','Wow. I usually check my phone in bed... for an hour.','劳伦：哇。我通常躺在床上刷手机……刷一个小时。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l26',6,'Ken','Ha! Do you eat breakfast?','肯：哈哈！你吃早饭吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l26',7,'Lauren','Sometimes. I usually just grab a coffee.','劳伦：偶尔吃。通常就是随手买杯咖啡。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l26',8,'Ken','I always eat breakfast. Eggs and toast.','肯：我每天都吃早饭。鸡蛋加烤面包片。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l26',9,'Lauren','Okay, okay. New plan: I''m going to get up early!','劳伦：行行行。新计划：我要早起！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l26',10,'Ken','Ha! You always say that.','肯：哈！你每次都这么说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l26',11,'Lauren','...Fair.','劳伦：……有道理。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l27',1,'Bella','So, Zach—what''s your new roommate like?','贝拉：说说，扎克——你的新室友怎么样？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l27',2,'Zach','Marco? He''s great. He works at an animal hospital.','扎克：马可？人特好。他在一家动物医院工作。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l27',3,'Bella','Cool! Does he like animals?','贝拉：酷！他喜欢动物吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l27',4,'Zach','He loves them! He has two cats.','扎克：爱得不行！他养了两只猫。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l27',5,'Bella','Aww. Does he cook?','贝拉：可爱。他做饭吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l27',6,'Zach','Yes, he does. He makes amazing pasta every Friday.','扎克：做的。他每周五做超好吃的意面。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l27',7,'Bella','Lucky you! Does he play music at night?','贝拉：你可真幸运！他晚上放音乐吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l27',8,'Zach','No, he doesn''t. He goes to bed at ten.','扎克：不放。他十点就睡了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l27',9,'Bella','Wow. He sounds perfect.','贝拉：哇，听起来完美啊。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l27',10,'Zach','Almost. He never washes the dishes!','扎克：差一点。他从来不洗碗！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l27',11,'Bella','Ha! Nobody''s perfect.','贝拉：哈哈！人无完人。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l28',1,NULL,'The Carters live in Austin, Texas.','卡特一家住在得克萨斯州奥斯汀。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l28',2,NULL,'Mr. Carter is a firefighter. He works at night and sleeps in the morning.','卡特先生是消防员。他上夜班，早晨睡觉。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l28',3,NULL,'Mrs. Carter teaches math at the middle school.','卡特太太在中学教数学。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l28',4,NULL,'She gets up at six and makes breakfast for the kids.','她六点起床，给孩子们做早餐。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l28',5,NULL,'Emma and Jack take the school bus at seven thirty.','艾玛和杰克七点半坐校车上学。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l28',6,NULL,'After school, Emma plays soccer and Jack does homework.','放学后，艾玛踢足球，杰克写作业。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l28',7,NULL,'The family eats dinner together at six.','一家人六点一起吃晚饭。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l28',8,NULL,'After dinner, they watch TV or play board games.','晚饭后，他们看电视或玩桌游。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l28',9,NULL,'On Fridays, they order pizza. It''s family tradition!','每逢周五，他们点披萨。这是家庭传统！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l28',10,NULL,'The Carters love their busy life.','卡特一家热爱他们忙碌的生活。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l29',1,'Raj','Molly? You''re here early! You usually come in at nine.','拉杰：莫莉？你今天来这么早！你平常都九点到。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l29',2,'Molly','I know! But today is different.','莫莉：是吧！但今天不一样。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l29',3,'Raj','And... are you drinking tea? You always drink coffee!','拉杰：而且……你在喝茶？你向来只喝咖啡的！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l29',4,'Molly','Ha! Yes. Today I''m drinking green tea.','莫莉：哈哈！对。今天我喝的是绿茶。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l29',5,'Raj','Okay, what''s going on?','拉杰：好吧，到底怎么回事？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l29',6,'Molly','I usually sit at my desk all day. But this week, I''m training for a 5K!','莫莉：我平常一整天坐在工位上。但这周，我在备战五公里跑！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l29',7,'Raj','A race? That''s awesome!','拉杰：比赛？太棒了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l29',8,'Molly','Yep. I run every evening now. Healthy life!','莫莉：对。我现在每天傍晚都跑步。健康生活！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l29',9,'Raj','Inspiring! I usually eat chips at my desk... and I''m eating chips right now.','拉杰：太励志了！我平常在工位上吃薯片……而且我现在正在吃。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l29',10,'Molly','Ha! Baby steps, Raj.','莫莉：哈哈！慢慢来，拉杰。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l29',11,'Raj','Okay, okay. Tomorrow I''m going to walk to work!','拉杰：行行行。明天我打算走路上班！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l30',1,'Cashier','Hi there! Are you finding everything okay?','收银员：您好！需要的东西都找到了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l30',2,'Grace','Yes, thanks!','格蕾丝：都找到了，谢谢！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l30',3,'Cashier','Okay... a bag of apples, a box of cereal...','收银员：好……一袋苹果、一盒麦片……') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l30',4,'Cashier','...and two bottles of orange juice. Is that all?','收银员：……还有两瓶橙汁。就这些吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l30',5,'Grace','Oh wait—I want these bananas too.','格蕾丝：等等——这些香蕉我也要。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l30',6,'Cashier','No problem. Anything else?','收银员：没问题。还要别的吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l30',7,'Grace','That''s it, thanks.','格蕾丝：就这些了，谢谢。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l30',8,'Cashier','Paper or plastic?','收银员：纸袋还是塑料袋？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l30',9,'Grace','Paper, please.','格蕾丝：纸袋，谢谢。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l30',10,'Cashier','Okay, that''s twelve fifty.','收银员：好的，一共十二块五。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l30',11,'Grace','Here you go. Have a good one!','格蕾丝：给您。祝您愉快！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l31',1,'Kayla','Good morning, Mr. Reed. This is Kayla.','凯拉：早上好，里德先生。我是凯拉。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l31',2,'Mr. Reed','Morning, Kayla! What''s up?','里德先生：早，凯拉！什么事？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l31',3,'Kayla','I don''t feel well today. I have a bad cold.','凯拉：我今天很不舒服，得了重感冒。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l31',4,'Mr. Reed','Oh no. Do you have a fever?','里德先生：哎呀。发烧吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l31',5,'Kayla','A little. And I have a sore throat too.','凯拉：有点。嗓子也疼。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l31',6,'Mr. Reed','That sounds rough. Stay home and rest.','里德先生：听着挺难受的。在家好好休息吧。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l31',7,'Kayla','Thank you. I''m really sorry.','凯拉：谢谢您。真不好意思。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l31',8,'Mr. Reed','Don''t worry about it. Drink a lot of water!','里德先生：没事别放心上。多喝水！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l31',9,'Kayla','I will. Thanks, Mr. Reed.','凯拉：我会的。谢谢您，里德先生。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l31',10,'Mr. Reed','Feel better soon!','里德先生：祝早日康复！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l32',1,'Dr. Patel','Hi, Kayla. What brings you in today?','帕特尔医生：你好，凯拉。今天哪里不舒服？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l32',2,'Kayla','I have a bad cold, and my throat hurts.','凯拉：我重感冒，嗓子疼。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l32',3,'Dr. Patel','Let''s take a look... Say "ahh."','帕特尔医生：我看看……说"啊——"。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l32',4,'Kayla','Ahh.','凯拉：啊——。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l32',5,'Dr. Patel','Okay. It''s not serious, but you must rest for three days.','帕特尔医生：嗯，不严重，但你必须休息三天。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l32',6,'Kayla','Three days? I have a big meeting on Friday!','凯拉：三天？我周五有个重要会议！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l32',7,'Dr. Patel','Health comes first. You must drink a lot of water.','帕特尔医生：健康第一。你必须多喝水。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l32',8,'Dr. Patel','And you mustn''t go to work. No exceptions!','帕特尔医生：而且千万不能去上班。没得商量！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l32',9,'Kayla','Okay, doctor. Anything else?','凯拉：好吧，医生。还有别的吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l32',10,'Dr. Patel','Yes—you mustn''t drink coffee for now. Only water and soup.','帕特尔医生：有——这段时间不许喝咖啡。只能喝水和汤。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l32',11,'Kayla','No coffee?! That''s the hard part.','凯拉：不能喝咖啡？！这才是最难的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l33',1,'Hailey','Dad, my friends are going to the mall today. Can I go?','海莉：爸，我朋友们今天去商场。我能去吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l33',2,'Dad','Sure. But first—is your room clean?','爸爸：可以。不过先问一句——你房间收拾了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l33',3,'Hailey','...Almost. Do I need to clean it right now?','海莉：……差不多吧。非得现在打扫吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l33',4,'Dad','Yes, you do. But you don''t need to wash the dishes—I''m on it.','爸爸：是的。不过碗你不用洗——我来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l33',5,'Hailey','Deal! What about homework?','海莉：成交！那作业呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l33',6,'Dad','It''s Saturday. You don''t need to do it today. But you need to finish it by Sunday night.','爸爸：今天周六，不必今天写。但周日晚上前必须写完。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l33',7,'Hailey','Fair. Anything else?','海莉：合理。还有吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l33',8,'Dad','One more thing: text me every hour.','爸爸：最后一条：每小时给我发条短信。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l33',9,'Hailey','Every hour?! Dad, you don''t need to worry so much.','海莉：每小时？！爸，你不用这么操心。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l33',10,'Dad','Ha! Okay—every two hours. Final offer.','爸爸：哈哈！行——每两小时。最终条件。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l33',11,'Hailey','Deal! You''re the best!','海莉：成交！你最好了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l34',1,'Omar','Morning, Nicole! How was your weekend?','奥马尔：早，妮可！周末过得怎么样？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l34',2,'Nicole','It was great! I was at the beach on Saturday.','妮可：特别好！我周六在海滩。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l34',3,'Omar','Nice! Was the weather good?','奥马尔：不错！天气好吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l34',4,'Nicole','Yes, it was. Sunny and warm all day.','妮可：好极了。一整天晴朗暖和。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l34',5,'Nicole','How about you? Where were you?','妮可：你呢？你去哪了？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l34',6,'Omar','I was at my cousin''s wedding in Dallas.','奥马尔：我在达拉斯参加我表哥的婚礼。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l34',7,'Nicole','Fun! Was the food good?','妮可：有意思！吃的好吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l34',8,'Omar','It was amazing. But the music was so loud!','奥马尔：超好吃。就是音乐太吵了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l34',9,'Nicole','Ha! Were your parents there?','妮可：哈哈！你爸妈也在吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l34',10,'Omar','Yes, they were. They were on the dance floor all night!','奥马尔：在。他们在舞池里跳了一整晚！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l34',11,'Nicole','I love that. Weekends are the best.','妮可：太可爱了。还是周末最棒。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l35',1,'June','Dad, look at this photo! Where was this?','琼：爸，看这张照片！这是在哪儿拍的？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l35',2,'Pete','Ha! That was the county fair last summer.','皮特：哈哈！那是去年夏天的县集市。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l35',3,'June','Oh yeah! There was a huge Ferris wheel!','琼：想起来了！那儿有个巨大的摩天轮！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l35',4,'Pete','Yep. And there were pony rides for the kids.','皮特：对。还有给孩子们骑的小马。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l35',5,'June','The food! There was so much funnel cake.','琼：还有吃的！好多漏斗蛋糕。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l35',6,'Pete','And there were corn dogs everywhere.','皮特：到处都是炸热狗棒。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l35',7,'June','Was there a pie contest?','琼：有派比赛吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l35',8,'Pete','Yes, there was. Grandma''s apple pie was second place!','皮特：有。奶奶的苹果派得了第二名！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l35',9,'June','Only second? Her pie is the best!','琼：才第二？她的派明明最好吃！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l35',10,'Pete','I know! The judges were wrong.','皮特：就是说！评委们瞎评。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l35',11,'June','Ha! Let''s go again this summer.','琼：哈哈！今年夏天咱们再去。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l36',1,'Ivy','Hey, Max. You look tired.','艾薇：嘿，麦克斯。你看起来很疲惫。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l36',2,'Max','Ugh. Yesterday was a mess.','麦克斯：呃，昨天简直一团糟。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l36',3,'Ivy','What happened?','艾薇：发生什么事了？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l36',4,'Max','Everything! First, I missed the bus.','麦克斯：全都出事！首先，我错过了公交。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l36',5,'Max','So I walked to work... in the rain.','麦克斯：所以我走路去上班……还下着雨。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l36',6,'Ivy','Oh no.','艾薇：不是吧。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l36',7,'Max','Then I spilled coffee on my laptop.','麦克斯：然后我把咖啡洒在了笔记本电脑上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l36',8,'Ivy','No way!','艾薇：不会吧！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l36',9,'Max','Yep. It stopped working for an hour. I called IT twice.','麦克斯：真的。它死机了一小时，我给技术部打了两次电话。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l36',10,'Max','And at lunch? They closed my favorite taco place.','麦克斯：午饭呢？我最爱的塔可店还关门了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l36',11,'Ivy','Wow. Well—you survived! Today is a new day.','艾薇：哇。不过——你挺过来了！今天又是新的一天。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l37',1,'Faith','Derek! You''re back! How was the road trip?','费丝：德里克！你回来啦！公路旅行怎么样？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l37',2,'Derek','Incredible. We drove to the Grand Canyon!','德里克：太震撼了。我们开车去了大峡谷！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l37',3,'Faith','No way! How long was the drive?','费丝：不会吧！开了多久？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l37',4,'Derek','Twelve hours. We took Route 66 for a while.','德里克：十二个小时。有一段我们走的是 66 号公路。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l37',5,'Faith','Classic! Tell me everything.','费丝：太经典了！快全讲给我听。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l37',6,'Derek','We saw wild horses on the way. And we ate at a tiny diner in Arizona.','德里克：路上我们看到了野马。还在亚利桑那一家小餐馆吃了饭。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l37',7,'Faith','A real diner? I love that.','费丝：正宗的美式小餐馆？我太爱了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l37',8,'Derek','Yep. I had a huge burger. So good.','德里克：对。我吃了个巨大的汉堡，绝了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l37',9,'Faith','And the canyon?','费丝：那峡谷呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l37',10,'Derek','We went at sunrise. It was unreal.','德里克：我们日出时去的。美得不真实。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l37',11,'Faith','Okay, I''m jealous. Next time, I''m coming!','费丝：好吧，我酸了。下次带上我！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l38',1,'Ray','Hi! How can I help you today?','雷：您好！有什么可以帮您？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l38',2,'Tessa','Hi. I bought these sneakers online last week.','泰莎：你好。这双运动鞋是我上周网上买的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l38',3,'Ray','Okay. Is there a problem?','雷：好的。有什么问题吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l38',4,'Tessa','Yes—they''re too small. I wore them once, and my feet hurt all day.','泰莎：有——太小了。我就穿了一次，脚疼了一整天。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l38',5,'Ray','Ouch. What size do you need?','雷：哎哟。您需要什么码？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l38',6,'Tessa','I got a nine, but I need a ten.','泰莎：我买的九码，但我需要十码。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l38',7,'Ray','Got it. Do you have the receipt?','雷：明白。小票带了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l38',8,'Tessa','Yes, right here. I paid with my card.','泰莎：带了，在这儿。我是刷卡付的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l38',9,'Ray','Perfect. One second... Okay, here''s the ten. Try them on!','雷：好的。稍等……十码的来了，试试！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l38',10,'Tessa','These are perfect. Not too big, not too small.','泰莎：完美。不大不小正合适。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l38',11,'Ray','Great! Have a good one!','雷：太好了！祝您愉快！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l39',1,'Gloria','Lakeside Dental, this is Gloria. How can I help you?','格洛丽亚：湖畔牙科，我是格洛丽亚。有什么可以帮您？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l39',2,'Victor','Hi, this is Victor Cruz. I missed my appointment this morning. I''m so sorry.','维克多：你好，我是维克多·克鲁兹。我今早的预约错过了，非常抱歉。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l39',3,'Gloria','Let me check... Did you have the nine o''clock?','格洛丽亚：我查一下……您约的是九点那场吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l39',4,'Victor','Yes, I did. My car didn''t start.','维克多：是的。我的车打不着火了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l39',5,'Gloria','Oh no. Did you call a mechanic?','格洛丽亚：哎呀。您叫修车师傅了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l39',6,'Victor','I did, but he didn''t come until noon.','维克多：叫了，但他中午才来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l39',7,'Gloria','That''s rough. Well, don''t worry—these things happen.','格洛丽亚：真够呛。不过别担心——这种事难免。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l39',8,'Victor','Thanks. Can I reschedule?','维克多：谢谢。我能改约吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l39',9,'Gloria','Sure. Did Dr. Kim see you last time, or Dr. Lopez?','格洛丽亚：当然。上次给您看诊的是金医生还是洛佩兹医生？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l39',10,'Victor','Dr. Kim. She was great.','维克多：金医生。她特别好。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l39',11,'Gloria','Perfect. How about Thursday at ten?','格洛丽亚：好的。周四十点怎么样？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l39',12,'Victor','Thursday works. Thank you so much!','维克多：周四可以。太感谢了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l40',1,'Carla','Okay, Wes. Big party this weekend. We have to get everything today.','卡拉：好了，韦斯。这周末大派对，我们今天必须买齐所有东西。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l40',2,'Wes','Copy that. How many burgers do we need?','韦斯：收到。我们需要多少个汉堡？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l40',3,'Carla','Twenty people... so forty burgers. And we have to buy buns too.','卡拉：二十个人……那就四十个汉堡。面包坯也得买。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l40',4,'Wes','How much soda do we need?','韦斯：汽水要多少？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l40',5,'Carla','A lot. Grab six big bottles.','卡拉：要很多。拿六大瓶。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l40',6,'Wes','On it. Do we have to get paper plates?','韦斯：这就拿。纸盘子也得买吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l40',7,'Carla','Yes—and cups and napkins. It''s a warehouse store. Everything is huge here!','卡拉：要——还有杯子和餐巾纸。这是仓储超市，什么都是巨型装！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l40',8,'Wes','Ha! True. How much is this giant ketchup?','韦斯：哈哈！确实。这瓶巨型番茄酱多少钱？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l40',9,'Carla','Eight bucks. Put it in the cart.','卡拉：八块。放购物车里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l40',10,'Wes','Wait—do we have to buy a 48-pack of water?','韦斯：等等——48 瓶装的水也得买吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l40',11,'Carla','Wes. Twenty people. Yes, we do.','卡拉：韦斯。二十个人。必须买。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l40',12,'Wes','Fair. This cart is full!','韦斯：有道理。购物车满了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l41',1,'Noah','Mia! How was Thanksgiving at your place?','诺亚：米娅！你家感恩节过得怎么样？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l41',2,'Mia','So good. Grandpa Joe cooked all day again.','米娅：太棒了。乔爷爷又掌勺了一整天。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l41',3,'Noah','Of course he did! What did he make?','诺亚：他肯定的！他做了什么？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l41',4,'Mia','Turkey, mashed potatoes, green bean casserole... everything.','米娅：火鸡、土豆泥、青豆焗菜……全套。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l41',5,'Noah','Did you make anything?','诺亚：你做了什么吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l41',6,'Mia','I made the mac and cheese. It went fast!','米娅：我做了芝士通心粉。一上桌就被抢光了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l41',7,'Noah','Nice! Did you guys watch the football game?','诺亚：厉害！你们看橄榄球赛了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l41',8,'Mia','We did. And after dinner, we played board games until midnight.','米娅：看了。晚饭后我们玩桌游玩到半夜。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l41',9,'Noah','Ha! Who won?','诺亚：哈哈！谁赢了？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l41',10,'Mia','Grandma. She always wins. She took a victory lap around the table!','米娅：奶奶。她永远赢。她还绕着桌子跑了一圈庆祝！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l41',11,'Noah','I love your family.','诺亚：我太爱你们家了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l41',12,'Mia','Come next year! We ate too much, but it was perfect.','米娅：明年来啊！我们吃撑了，但一切完美。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l42',1,'Max','Ivy! Big smile today. What''s up?','麦克斯：艾薇！今天笑得这么开心，什么好事？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l42',2,'Ivy','Tomorrow is vacation day! We''re going to fly to Miami.','艾薇：明天就放假啦！我们要飞迈阿密。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l42',3,'Max','Nice! I went to Miami last year. It was amazing.','麦克斯：太好了！我去年去过迈阿密，特别棒。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l42',4,'Ivy','Really? What did you do there?','艾薇：真的？你在那儿都干了什么？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l42',5,'Max','We swam every morning and ate seafood every night.','麦克斯：我们每天早上游泳，每晚吃海鲜。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l42',6,'Ivy','That''s the dream. I''m making a packing list right now!','艾薇：这就是梦想生活。我现在正在列行李清单呢！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l42',7,'Max','Ha! Classic Ivy. What are you going to do there?','麦克斯：哈哈！很艾薇。你们打算去那儿干什么？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l42',8,'Ivy','We''re going to visit South Beach. And I''m going to try key lime pie!','艾薇：我们要去南海滩。我还要尝尝青柠派！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l42',9,'Max','You must try it. I had three slices last year.','麦克斯：必须尝。我去年吃了三块。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l42',10,'Ivy','Three?! Okay, goals.','艾薇：三块？！行，这就是目标。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l42',11,'Max','Send photos! Last year I forgot my camera.','麦克斯：多发照片！我去年把相机给忘了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l42',12,'Ivy','I will! See you in a week!','艾薇：一定！一周后见！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l43',1,'Colin','Faith, nice poster! What''s that?','科林：费丝，这海报不错！是什么？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l43',2,'Faith','My national park map! I scratch off every park I visit.','费丝：我的国家公园地图！每去一个公园就刮开一格。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l43',3,'Colin','Cool! Have you been to Yellowstone?','科林：酷！你去过黄石公园吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l43',4,'Faith','Yes, I have. Twice! I''ve seen the geysers.','费丝：去过，两次！我看过那些间歇泉。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l43',5,'Colin','Nice. Have you ever been to Yosemite?','科林：厉害。那你去过优胜美地吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l43',6,'Faith','No, I haven''t. Not yet. It''s on my list!','费丝：还没有。不过在我的清单上！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l43',7,'Colin','I''ve been there three times. The waterfalls are unreal.','科林：我去过三次。那些瀑布美到不真实。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l43',8,'Faith','Okay, now I''m jealous. What about the Grand Canyon?','费丝：好吧，我酸了。大峡谷呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l43',9,'Colin','Never. I''ve never been there.','科林：从没去过。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l43',10,'Faith','My friend Derek drove there last month. He loved it.','费丝：我朋友德里克上个月开车去了，爱到不行。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l43',11,'Colin','Ha! Okay, deal—Yosemite for you, Grand Canyon for me.','科林：哈哈！行，说定了——你去优胜美地，我去大峡谷。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l43',12,'Faith','It''s a plan!','费丝：就这么定了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l44',1,'Agent','Thanks for calling Redline Insurance. How can I help?','客服：感谢致电红线保险。有什么可以帮您？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l44',2,'Victor','Hi, this is Victor Cruz. Someone has just hit my car!','维克多：你好，我是维克多·克鲁兹。有人刚剐了我的车！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l44',3,'Agent','Oh no. Are you okay?','客服：哎呀。您人没事吧？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l44',4,'Victor','I''m fine. I was in the store. It happened in the parking lot.','维克多：我没事，当时在店里。事情发生在停车场。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l44',5,'Agent','Okay. Have you called the police yet?','客服：好的。您报警了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l44',6,'Victor','Not yet. I''ve just found the damage.','维克多：还没。我刚发现车损。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l44',7,'Agent','Got it. Have you taken photos yet?','客服：明白。拍照了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l44',8,'Victor','Yes, I''ve just taken ten photos. And the other driver has left a note!','维克多：拍了，刚拍了十张。而且对方司机留了张字条！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l44',9,'Agent','Perfect—that''s great news. Has anyone seen the accident?','客服：太好了——这是好消息。有人目击事故吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l44',10,'Victor','Yes, a woman saw it. She hasn''t left yet—she''s right here.','维克多：有位女士看到了。她还没走——就在旁边。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l44',11,'Agent','Excellent. You''re doing everything right, Mr. Cruz.','客服：非常好。您的处理全都到位，克鲁兹先生。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l44',12,'Victor','Ha! Well—my car doesn''t think so.','维克多：哈！可我的车不这么想。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l45',1,'Dana','Wendy?! Is that you?','达娜：温蒂？！是你吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l45',2,'Wendy','Dana! Oh my gosh! It''s been forever!','温蒂：达娜！天哪！这也太久没见了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l45',3,'Dana','How long has it been? Ten years?','达娜：多少年了？十年？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l45',4,'Wendy','Twelve! We haven''t seen each other since high school.','温蒂：十二年！高中毕业后咱们就没见过。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l45',5,'Dana','Crazy. So what''s new? Where do you live now?','达娜：太疯狂了。近况如何？现在住哪儿？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l45',6,'Wendy','I''ve lived in Denver for five years. I love it there.','温蒂：我在丹佛住了五年了。特别喜欢那儿。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l45',7,'Dana','Nice! Are you still a nurse?','达娜：真好！还在做护士吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l45',8,'Wendy','Yep. I''ve worked at the same hospital since 2021.','温蒂：对。2021 年起我一直在同一家医院工作。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l45',9,'Dana','Wow. And hey—you haven''t changed at all!','达娜：哇。话说——你一点都没变！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l45',10,'Wendy','Ha! You too. Do you have time for coffee?','温蒂：哈哈！你也是。有空喝杯咖啡吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l45',11,'Dana','For you? Always. Let''s catch up!','达娜：为了你？永远有空。走，好好叙叙旧！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l46',1,'Megan','Carlos! Big news—the Johnsons have sold their house!','梅根：卡洛斯！大新闻——约翰逊家把房子卖了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l46',2,'Carlos','No way! When did they sell it?','卡洛斯：不会吧！什么时候卖的？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l46',3,'Megan','Last Tuesday. It sold in two days!','梅根：上周二。挂牌两天就卖掉了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l46',4,'Carlos','Two days?! The market is wild.','卡洛斯：两天？！这房市太疯狂了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l46',5,'Megan','Yep. And guess what—I''ve met the new owners.','梅根：对。你猜怎么着——我已经见过新房主了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l46',6,'Carlos','Really? What are they like?','卡洛斯：真的？他们人怎么样？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l46',7,'Megan','Super nice. I met them yesterday at the mailbox.','梅根：特别好。我昨天在信箱那儿碰到的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l46',8,'Carlos','Nice. Have they moved in yet?','卡洛斯：真好。他们搬进来了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l46',9,'Megan','Not yet. The moving truck arrived this morning, but they haven''t unpacked.','梅根：还没。搬家卡车今早到了，但东西还没拆箱。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l46',10,'Carlos','Let''s say hi this weekend.','卡洛斯：这周末咱们去打个招呼吧。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l46',11,'Megan','Good idea. I''m going to bake cookies for them!','梅根：好主意。我要给他们烤饼干！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l46',12,'Carlos','Classic Megan. They''re lucky neighbors!','卡洛斯：太梅根了。他们真是幸运的邻居！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l47',1,'Carlos','So I met Jonas, the new neighbor. Guess what—he''s a pilot!','卡洛斯：我见到新邻居乔纳斯了。你猜怎么着——他是飞行员！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l47',2,'Megan','A pilot? That''s so cool!','梅根：飞行员？太酷了吧！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l47',3,'Carlos','Yep. He''ll fly to Tokyo next week.','卡洛斯：对。他下周要飞东京。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l47',4,'Megan','Wow. Pilots see the whole world.','梅根：哇。飞行员能看遍全世界。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l47',5,'Carlos','He said something funny: "I''ll sleep in three countries this month."','卡洛斯：他说了句好玩的："这个月我要在三个国家睡觉。"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l47',6,'Megan','Ha! What a life. Will his family move here too?','梅根：哈哈！这日子真棒。他家人也会搬来吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l47',7,'Carlos','Yes, they will. His wife will start a new job downtown in June.','卡洛斯：会。他妻子六月要在市中心开始新工作。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l47',8,'Megan','Great. And their kids?','梅根：真好。孩子们呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l47',9,'Carlos','Two boys. They''ll go to Maplewood Elementary in the fall.','卡洛斯：两个男孩。秋天他们会去枫木小学上学。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l47',10,'Megan','Perfect. The block party is next month—they''ll love it!','梅根：完美。下个月就是街区派对——他们肯定喜欢！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l47',11,'Carlos','Good call. I''ll invite them tomorrow.','卡洛斯：好主意。我明天就去邀请他们。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l47',12,'Megan','And I''ll bring my famous lemonade!','梅根：那我带上我的招牌柠檬水！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l48',1,'Ivy','Excuse me. Flight 214 to Miami—is it on time?','艾薇：打扰一下。飞迈阿密的 214 航班——准点吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l48',2,'Agent','Let me check... I''m sorry, that flight is delayed.','值机员：我查一下……抱歉，该航班延误了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l48',3,'Ivy','Oh no. When will it leave?','艾薇：哎呀。那几点起飞？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l48',4,'Agent','It will leave at 3:45, from Gate 12.','值机员：3 点 45 分起飞，12 号登机口。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l48',5,'Ivy','Okay. And when will it arrive in Miami?','艾薇：好的。几点到迈阿密？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l48',6,'Agent','It will arrive at 7:30 local time.','值机员：当地时间 7 点半到达。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l48',7,'Ivy','Got it. Will I have time for lunch?','艾薇：明白。我还来得及吃午饭吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l48',8,'Agent','Sure. Boarding will start at 3:15. You have two hours.','值机员：来得及。3 点 15 分开始登机，您还有两小时。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l48',9,'Ivy','Perfect. One more thing—which way is the food court?','艾薇：太好了。还有一件事——美食广场往哪边走？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l48',10,'Agent','Go straight, past Gate 8. You''ll see it on the left.','值机员：直走，过 8 号登机口，左手边就能看到。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l48',11,'Ivy','Thank you so much!','艾薇：太感谢了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l48',12,'Agent','You''re welcome. Have a safe flight!','值机员：不客气。祝您旅途平安！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',1,'Jenna','Hi! Front desk. How can I help?','珍娜：您好！这里是前台。有什么可以帮您？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',2,'Paul','Hi. I left my water bottle here yesterday. Is it in the lost and found?','保罗：你好。我昨天把水瓶落在这儿了。失物招领处有吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',3,'Jenna','Let''s see... We have three bottles. Is this blue one yours?','珍娜：我看看……这儿有三个水瓶。这个蓝色的是你的吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',4,'Paul','No, that''s not mine. Mine is black with a sticker.','保罗：不，那不是我的。我的是黑色的，带贴纸。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',5,'Jenna','Hmm. This black one?','珍娜：嗯……这个黑色的？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',6,'Paul','Yes! That''s mine. Thank you!','保罗：对！就是我的。谢谢！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',7,'Jenna','Great. Oh—and is this towel yours too?','珍娜：太好了。哦——这条毛巾也是你的吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',8,'Paul','No. My friend Leo was with me... Actually, that''s his. Same team logo.','保罗：不是。我朋友利奥当时和我一起……其实那是他的，同款队标。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',9,'Jenna','Got it. And these headphones?','珍娜：明白。那这副耳机呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',10,'Paul','Not ours. Sorry.','保罗：不是我们的。抱歉。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',11,'Jenna','No problem. Someone will come for them—they always do.','珍娜：没关系。总会有人来认领的——一向如此。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l49',12,'Paul','Thanks so much. You''re the best!','保罗：太感谢了。你最棒了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',1,'Kyle','Andre! Are you okay? That fall looked bad.','凯尔：安德烈！你没事吧？刚才摔得挺重。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',2,'Andre','I''m fine, I''m fine. I hurt myself a little.','安德烈：没事没事。就伤到自己一点点。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',3,'Kyle','A little? You can''t stand up by yourself!','凯尔：一点点？你自己都站不起来！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',4,'Andre','Okay... my ankle hurts. But I can walk it off.','安德烈：好吧……脚踝疼。但我走两步就没事了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',5,'Kyle','No way. Sit down. Don''t push yourself.','凯尔：想都别想。坐下，别硬撑。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',6,'Andre','Kyle, relax. It''s just a game.','安德烈：凯尔，放松。就是打个球而已。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',7,'Kyle','Dude, last month Marcus hurt himself and played anyway. He was out for six weeks!','凯尔：哥们儿，上个月马库斯伤了还硬打，结果伤停六周！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',8,'Andre','...Fair. Okay, ice it is.','安德烈：……有道理。行，冰敷吧。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',9,'Kyle','Smart. I''ll get the first aid kit. Help yourself to my water.','凯尔：明智。我去拿急救箱。我的水你随便喝。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',10,'Andre','Thanks, man. You take care of everyone.','安德烈：谢了，兄弟。你把每个人都照顾得很好。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l50',11,'Kyle','Somebody has to! Now take care of yourself.','凯尔：总得有人操心！现在，照顾好你自己。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',1,'Hailey','DAD! DAD! It''s here! The email from Westfield College!','海莉：爸！爸！来了！韦斯特菲尔德学院的邮件！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',2,'Dad','Oh wow. Have you opened it yet?','爸爸：哇。你打开了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',3,'Hailey','Not yet! I''m scared. You open it!','海莉：还没！我不敢。你来打开！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',4,'Dad','No way—this is your moment. I''ve already called your mom, by the way. She''s driving home right now.','爸爸：不行——这是属于你的时刻。顺便说一句，我已经给你妈打过电话了，她正开车往家赶。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',5,'Hailey','You''ve already told Mom?! Dad!','海莉：你已经告诉妈了？！爸！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',6,'Dad','Of course! Okay, deep breath. Open it.','爸爸：当然！好了，深呼吸。打开吧。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',7,'Hailey','Okay... okay... "Dear Hailey, congratulations! We are..." I GOT IN!','海莉：好……好……"亲爱的海莉，祝贺你！我们……"我被录取了！！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',8,'Dad','YES! I knew it! I never doubted you!','爸爸：太棒了！我就知道！我从没怀疑过你！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',9,'Hailey','I''ve just read it three times. It''s real!','海莉：我刚刚连读了三遍。是真的！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',10,'Dad','Have you told your friends yet?','爸爸：告诉朋友们了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',11,'Hailey','Not yet—wait, Mom has just texted me: "SCREAMING." She already knows?!','海莉：还没——等等，妈刚给我发短信："尖叫中"。她已经知道了？！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l51',12,'Dad','...I texted her a photo. Sorry not sorry!','爸爸：……我把截图发给她了。抱歉，但我不后悔！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',1,'Sean','Nadia, it''s midnight. Go home. You''ve studied enough.','肖恩：娜迪亚，都半夜了。回家吧，你复习得够多了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',2,'Nadia','I can''t! The final is tomorrow, and chapter nine is too hard for me.','娜迪亚：不行！明天就期末考了，第九章对我来说太难了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',3,'Sean','It''s not too hard. You''re just too tired to think.','肖恩：不是太难，是你累得没法思考了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',4,'Nadia','Maybe. But I don''t have enough time!','娜迪亚：也许吧。但我时间不够了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',5,'Sean','You do. The test is at 2 p.m. Sleep now, review in the morning.','肖恩：够的。考试下午两点。现在睡觉，早上再过一遍。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',6,'Nadia','Is eight hours enough for chapter nine?','娜迪亚：八个小时够我啃第九章吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',7,'Sean','For you? More than enough. You''ve got this.','肖恩：对你来说？绰绰有余。你可以的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',8,'Nadia','Okay, okay. But this coffee is too cold to drink anyway.','娜迪亚：好吧好吧。反正这杯咖啡也凉得没法喝了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',9,'Sean','Ha! That''s your fourth cup. That''s enough coffee for one night.','肖恩：哈哈！那是你第四杯了。一晚上喝这么多咖啡够了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',10,'Nadia','...Fair. Pack up. Let''s go.','娜迪亚：……有道理。收拾东西，走。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l52',11,'Sean','Good call. See you at the final!','肖恩：明智。考场见！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',1,'Erin','Okay, Jamal. I read your essay. It''s really good!','艾琳：好了，贾马尔。我读完你的作文了。写得真不错！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',2,'Jamal','Really? Be honest. Grade it hard.','贾马尔：真的？说实话，往狠了批。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',3,'Erin','Okay... here: "He runs quick." That needs an L-Y: "quickly."','艾琳：好……这里："He runs quick."，得加 -ly："quickly"。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',4,'Jamal','Ah, right. Adverb.','贾马尔：啊对，副词。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',5,'Erin','Same here: "She sings beautiful." → "She sings beautifully."','艾琳：这儿也一样："She sings beautiful" 要改成 "beautifully"。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',6,'Jamal','Got it. Adjectives describe things, adverbs describe actions.','贾马尔：明白了。形容词描述事物，副词描述动作。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',7,'Erin','Exactly! But careful—some words don''t change. "He works hard" is correct.','艾琳：完全正确！不过小心——有些词不变形。"He works hard" 就是对的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',8,'Jamal','Not "hardly"?','贾马尔：不是 "hardly"？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',9,'Erin','No! "Hardly" means "almost not." He hardly works = he''s lazy!','艾琳：不是！"hardly" 意思是"几乎不"。He hardly works = 他很懒！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',10,'Jamal','Whoa. English is tricky.','贾马尔：哇哦。英语真难缠。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',11,'Erin','A little. But your story is great. You write well!','艾琳：有一点。不过你的故事很棒，你写得真好！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l53',12,'Jamal','Thanks! You explain things clearly.','贾马尔：谢谢！你讲得也特别清楚。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',1,'Ray','Hey, welcome back! The sneaker lady!','雷：嘿，欢迎回来！运动鞋女士！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',2,'Tessa','Ha! That''s me. Today I need jeans.','泰莎：哈哈！正是本人。今天我要买牛仔裤。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',3,'Ray','Sure. Try these—they''re very popular.','雷：好嘞。试试这条——特别受欢迎。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',4,'Tessa','Hmm, they''re nice, but a little tight. Do you have a bigger size?','泰莎：嗯，不错，就是有点紧。有大一号的吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',5,'Ray','Of course. These are bigger... and honestly, they''re softer too.','雷：当然。这条大一号……而且说实话，还更软。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',6,'Tessa','Ooh, you''re right. These feel softer. Way better!','泰莎：哦，真的。这条摸着更软，好太多了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',7,'Ray','And they''re cheaper than the first pair. Twenty bucks cheaper.','雷：而且比第一条便宜——便宜二十块。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',8,'Tessa','Cheaper AND better? Sold!','泰莎：又便宜又好？成交！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',9,'Ray','Ha! One tip: they run big. Maybe try the smaller size in black.','雷：哈哈！一个小建议：这款尺码偏大，黑色可以试小一号。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',10,'Tessa','Good call. Hmm—is the black cooler than the blue?','泰莎：好主意。嗯——黑色比蓝色更酷吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',11,'Ray','Honestly? The black is way cooler.','雷：说实话？黑色酷太多了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l54',12,'Tessa','Black it is. You''re better at this than me!','泰莎：那就黑色。你比我在行多了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',1,'Wes','Okay, Carla—anniversary dinner. Bella Roma or The Harbor House?','韦斯：好了，卡拉——纪念日晚餐。贝拉罗马还是海港小馆？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',2,'Carla','Ooh, tough call. Bella Roma is more romantic.','卡拉：哦，难选。贝拉罗马更浪漫。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',3,'Wes','True. But The Harbor House is more famous. The view is incredible.','韦斯：确实。但海港小馆更有名，那景色绝了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',4,'Carla','It''s also more expensive. Way more expensive.','卡拉：它也更贵。贵得多得多。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',5,'Wes','Hey, it''s our tenth anniversary! Tonight, money is not the problem.','韦斯：嘿，这可是我们十周年！今晚，钱不是问题。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',6,'Carla','Ha! Okay, big spender. Is the food better there?','卡拉：哈哈！好嘛，大款。那儿的菜更好吃吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',7,'Wes','Honestly, Bella Roma''s pasta is more delicious. But the Harbor''s seafood is fresher.','韦斯：说实话，贝拉罗马的意面更好吃。不过海港的海鲜更新鲜。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',8,'Carla','Hmm. Which one is more comfortable? I want a quiet night.','卡拉：嗯。哪家更舒服？我想要个安静的夜晚。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',9,'Wes','Bella Roma. The Harbor is always crowded—and louder.','韦斯：贝拉罗马。海港总是人挤人——还更吵。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',10,'Carla','Then it''s Bella Roma. Romantic, delicious, and quieter.','卡拉：那就贝拉罗马。浪漫、好吃、还更安静。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',11,'Wes','Perfect. I''ll call them right now.','韦斯：完美。我这就打电话订位。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l55',12,'Carla','Best husband ever.','卡拉：史上最佳老公。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',1,'Big Al','Welcome to Big Al''s Autos! I''m Big Al. What are you looking for?','大艾尔：欢迎来到大艾尔车行！我就是大艾尔。您想找什么车？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',2,'Nicole','Hi! I need a car for work. Safe, cheap, and easy to park.','妮可：你好！我要买辆通勤车。安全、便宜、好停。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',3,'Big Al','Easy! This one is the cheapest car on the lot. Nine thousand.','大艾尔：小意思！这辆是全场最便宜的，九千。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',4,'Nicole','Hmm. And the safest?','妮可：嗯。那最安全的呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',5,'Big Al','That''s this one—five stars. It''s also the most popular model this year.','大艾尔：是这辆——五星安全。它还是今年最热销的车型。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',6,'Nicole','Nice. But it''s the biggest one here. I need something smaller.','妮可：不错。但它是这儿最大的一辆，我要小一点的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',7,'Big Al','Then this blue one. Small, safe, and the newest on the lot.','大艾尔：那就这辆蓝色的。小巧、安全，还是全场最新款。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',8,'Nicole','What''s the price?','妮可：什么价？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',9,'Big Al','For you? Twelve thousand. Best price in town!','大艾尔：给您？一万二。全城最低价！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',10,'Nicole','Hmm... it''s the nicest one, honestly. Can I test-drive it?','妮可：嗯……说实话它确实是最合我意的。能试驾吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',11,'Big Al','Of course! Here are the keys. Worst case, you get a fun ride!','大艾尔：当然！钥匙给您。大不了，就当兜个风！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l56',12,'Nicole','Ha! Let''s go.','妮可：哈哈！走起。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',1,'Jamal','Oh no. This meter only takes quarters.','贾马尔：糟了。这咪表只收 25 美分硬币。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',2,'Jamal','Excuse me! Do you have any quarters?','贾马尔：打扰一下！您有 25 美分硬币吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',3,'Grace','Let me check my purse... Hmm, I don''t think I have any.','格蕾丝：我看看包……嗯，好像一个也没有。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',4,'Jamal','No worries. Thanks anyway.','贾马尔：没关系。还是谢谢您。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',5,'Grace','Wait—there are some coins in my car. One second.','格蕾丝：等等——我车里有些硬币。稍等。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',6,'Grace','Okay: dimes, nickels... and quarters! How many do you need?','格蕾丝：来了：10 美分的、5 美分的……还有 25 美分的！你要几个？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',7,'Jamal','Two, if you have any.','贾马尔：两个，如果您有的话。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',8,'Grace','I have three. Take them all.','格蕾丝：我有三个。都拿去吧。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',9,'Jamal','You''re a lifesaver! Here—I have some bills. Let me pay you back.','贾马尔：您真是救星！这儿——我有纸币，我还您钱。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',10,'Grace','No need. It''s seventy-five cents!','格蕾丝：不用啦。总共七毛五！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',11,'Jamal','Ha! Okay. Well—none of my friends are this nice.','贾马尔：哈哈！好吧。说真的——我朋友里都没这么好心的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l57',12,'Grace','Pay it forward! Have a good one!','格蕾丝：把善意传下去就行！祝愉快！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',1,'Faith','Derek! Somebody is at the door again!','费丝：德里克！又有人在门口！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',2,'Derek','Coming! ...Nobody''s here. Just a pumpkin on the steps.','德里克：来了！……没人啊。台阶上就一个南瓜。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',3,'Faith','Weird. That''s the third time tonight.','费丝：怪了。今晚第三次了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',4,'Derek','Wait—did anybody take candy from the bowl?','德里克：等等——有人从糖果碗里拿糖了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',5,'Faith','Let me see... The bowl is empty! Somebody took everything!','费丝：我看看……碗空了！有人把糖全拿走了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',6,'Derek','No way. Okay, everybody stay calm. I''ll check the camera.','德里克：不会吧。好，大家保持冷静。我去看监控。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',7,'Faith','"Everybody"? It''s just us, Derek.','费丝："大家"？就咱俩，德里克。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',8,'Derek','...Okay, both of us stay calm. Look—the camera!','德里克：……好吧，咱俩保持冷静。看——监控！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',9,'Faith','Is that... a dog? A dog in a dinosaur costume?!','费丝：那是……一只狗？穿恐龙服的狗？！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',10,'Derek','Ha! The Hendersons'' dog! He took the whole bowl!','德里克：哈哈！亨德森家的狗！它把一整碗都端走了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',11,'Faith','Nobody will believe this. Send the video to everybody!','费丝：没人会信的。把视频发给所有人！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l58',12,'Derek','Best Halloween ever.','德里克：史上最棒万圣节。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',1,'Molly','Raj, why is your arm in a cast?!','莫莉：拉杰，你胳膊怎么打上石膏了？！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',2,'Raj','Funny story. I was riding my bike when a squirrel ran into the road.','拉杰：说来好笑。我正骑着车，一只松鼠突然窜上了路。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',3,'Molly','A squirrel?!','莫莉：松鼠？！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',4,'Raj','Yep. I was going downhill, so I turned fast... and met a tree.','拉杰：对。当时正下坡，我猛一转弯……跟一棵树来了个会面。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',5,'Molly','Oh no! Were you wearing a helmet?','莫莉：天哪！你当时戴头盔了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',6,'Raj','I was! Safety first. The helmet is fine. My arm... less fine.','拉杰：戴了！安全第一。头盔没事。胳膊……不太没事。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',7,'Molly','What happened to the squirrel?','莫莉：那松鼠呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',8,'Raj','Oh, he was totally fine. He was eating an acorn while I was lying on the ground.','拉杰：哦，它好得很。我躺在地上的时候，它在旁边吃橡果。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',9,'Molly','Ha! Rude.','莫莉：哈哈！太没礼貌了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',10,'Raj','Right? Anyway, six weeks in a cast. No biking.','拉杰：可不是嘛。总之，石膏六周，不许骑车。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',11,'Molly','Well—while you were breaking your arm, I was running my first 5K!','莫莉：嗯——你摔胳膊的时候，我跑完了人生第一个五公里！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l59',12,'Raj','No way! Molly! Okay, that''s the best news today.','拉杰：不会吧！莫莉！好，这是今天最棒的消息。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',1,NULL,'Last month, Kyle and Andre went camping at Bear Lake.','上个月，凯尔和安德烈去熊湖露营。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',2,NULL,'On the first night, they were sitting by the fire and telling stories.','第一晚，他们正坐在篝火旁讲故事。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',3,NULL,'Suddenly, they heard a strange sound in the trees.','突然，他们听到树林里有奇怪的声响。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',4,NULL,'"Shh! Did you hear that?" Kyle whispered.','"嘘！你听到了吗？"凯尔低声说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',5,NULL,'Something was moving behind their tent.','有什么东西正在帐篷后面移动。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',6,NULL,'Andre grabbed his flashlight, but his hands were shaking.','安德烈抓起手电筒，但他的手在发抖。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',7,NULL,'While Kyle was looking for his phone, the sound came closer... and closer.','凯尔翻找手机的时候，那声音越来越近……越来越近。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',8,NULL,'Then Andre turned on the light. Nobody was there—just a fat raccoon!','然后安德烈打开了灯。没有人——只有一只肥浣熊！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',9,NULL,'It was eating their marshmallows and looking right at them.','它正吃着他们的棉花糖，还直勾勾地盯着他们。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',10,NULL,'The raccoon finished the whole bag and walked away slowly, like a boss.','浣熊吃完了一整袋，然后慢悠悠地走了，像个大佬。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l60',11,NULL,'Kyle and Andre laughed for ten minutes. Now they call that campsite "Raccoon Palace."','凯尔和安德烈笑了十分钟。现在他们管那个营地叫"浣熊行宫"。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',1,'Ruth','Welcome to Page Turner Books! Looking for anything special?','露丝：欢迎来到"翻不停"书店！想找什么特别的书吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',2,'Emma','Yes! I need a gift for my brother. He''s someone who reads everything.','艾玛：对！我要给我哥挑份礼物。他是个什么都读的人。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',3,'Ruth','Nice. What does he like?','露丝：真好。他喜欢什么类型？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',4,'Emma','Mysteries. He loves writers who build slow, smart stories.','艾玛：悬疑。他喜欢那种慢慢铺陈、构思聪明的作家。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',5,'Ruth','Then he''ll love this one. It''s about a detective who never asks questions.','露丝：那他一定会爱这本。讲的是一个从不提问的侦探。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',6,'Emma','A detective who never asks questions? How does that work?','艾玛：从不提问的侦探？那案子怎么破？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',7,'Ruth','Ha! That''s the mystery! People who read it can''t stop talking about it.','露丝：哈哈！这就是悬念所在！读过的人都停不下来地讨论它。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',8,'Emma','Sold! And something for my mom? She''s a person who cooks a lot.','艾玛：成交！再给我妈挑一本？她是个特别爱做饭的人。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',9,'Ruth','Easy—this cookbook. The chef who wrote it has a diner in Texas.','露丝：简单——这本菜谱。写它的大厨在得州开了家小餐馆。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',10,'Emma','Perfect. You''re a bookseller who really knows books!','艾玛：完美。你真是个懂书的书店店员！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l61',11,'Ruth','Ha! That''s the nicest thing a customer said all week.','露丝：哈哈！这是本周顾客对我说过的最好听的话。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',1,'Jake','Sara, look at this place! A market that sells everything!','杰克：萨拉，看看这地方！一个什么都卖的市集！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',2,'Sara','I know! Okay—I want a lamp that matches my new desk.','萨拉：可不是！好——我要找一盏配得上我新书桌的台灯。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',3,'Jake','There''s a table over there which has old lamps. Green ones, gold ones...','杰克：那边有张桌子摆着旧台灯。绿的、金的……') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',4,'Sara','Ooh! And look—a box that is full of old books!','萨拉：哦！你看——一箱子全是旧书！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',5,'Jake','Of course you found the books. Classic Sara.','杰克：你果然直奔书去了。太萨拉了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',6,'Sara','This one is a mystery which was famous in the 1960s. Two bucks!','萨拉：这本是六十年代很有名的悬疑小说。才两块！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',7,'Jake','Nice find! I want a jacket that looks cool but costs nothing.','杰克：好眼力！我想找一件看着酷但不要钱的夹克。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',8,'Sara','Ha! Good luck. Oh—that stand has records which are only a dollar!','萨拉：哈哈！祝你好运。哦——那个摊的黑胶唱片只要一块钱！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',9,'Jake','Whoa. Okay, this is a place that we need to visit every weekend.','杰克：哇哦。行，这地方咱们得每周末都来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',10,'Sara','Deal. But first—help me carry this lamp that I just bought.','萨拉：成交。不过先——帮我搬一下我刚买的这盏台灯。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',11,'Jake','...It''s heavy, isn''t it?','杰克：……很沉，对吧？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l62',12,'Sara','Some things never change!','萨拉：有些事永远不会变！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',1,'Jonas','Carlos! Quick question. I got a letter from the HOA... What''s an HOA?','乔纳斯：卡洛斯！问个小问题。我收到一封 HOA 的信……HOA 是什么？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',2,'Carlos','Ha! Welcome to the neighborhood. It''s the homeowners association. They have rules.','卡洛斯：哈哈！欢迎来到咱们社区。那是业主协会，他们有一堆规定。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',3,'Jonas','Rules? Like what?','乔纳斯：规定？比如？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',4,'Carlos','Well, you have to mow your lawn every two weeks.','卡洛斯：嗯，你每两周得修剪一次草坪。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',5,'Jonas','Every two weeks?! I fly to Tokyo every two weeks!','乔纳斯：每两周？！我每两周还得飞一趟东京呢！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',6,'Carlos','Ha! Then you have to hire somebody. My guy is cheap—I''ll send you his number.','卡洛斯：哈哈！那你得雇个人。我认识的师傅便宜——我把号码发你。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',7,'Jonas','Thanks. Anything else I have to do?','乔纳斯：谢了。还有什么必须做的吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',8,'Carlos','You have to put the trash cans away by Friday night. And you can''t paint your door purple.','卡洛斯：垃圾桶周五晚上前得收回去。还有，门不能刷成紫色。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',9,'Jonas','Purple? Who paints a door purple?','乔纳斯：紫色？谁会把门刷成紫色？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',10,'Carlos','The Hendersons did. Once. There was a meeting.','卡洛斯：亨德森家干过。就一次。后来开了个会。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',11,'Jonas','Ha! Okay. Do I have to go to the meetings?','乔纳斯：哈哈！好吧。会议我必须参加吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l63',12,'Carlos','You don''t have to. But there are free cookies.','卡洛斯：不必。不过有免费饼干。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',1,'Nina','Rosa, look at that guy by the window. Three laptops!','妮娜：罗莎，看窗边那个人。三台笔记本电脑！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',2,'Rosa','Three?! He must be a programmer.','罗莎：三台？！他一定是个程序员。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',3,'Nina','Or a spy.','妮娜：也可能是间谍。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',4,'Rosa','Ha! And that woman with all the books? She must be a student. Finals week.','罗莎：哈哈！那个抱着一摞书的女士呢？她一定是学生。期末周嘛。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',5,'Nina','She must be so tired. That''s her third coffee.','妮娜：她一定累坏了。那是她第三杯咖啡了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',6,'Rosa','Been there.','罗莎：我懂，经历过。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',7,'Nina','Ooh—and the man in the suit? He keeps checking his watch.','妮娜：哦——那个穿西装的男士呢？他一直在看表。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',8,'Rosa','He must be waiting for someone. A big meeting, maybe.','罗莎：他一定在等人。也许是个重要会议。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',9,'Nina','Or a first date! Look—flowers under the table!','妮娜：也可能是初次约会！看——桌子底下有花！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',10,'Rosa','No way! You''re right. He must be so nervous.','罗莎：不会吧！你说对了。他一定紧张死了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',11,'Nina','Aww. Okay, new game: guess everybody''s story.','妮娜：可爱。好，新游戏：猜每个人的故事。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l64',12,'Rosa','Ha! We must be the nosiest people in this coffee shop.','罗莎：哈哈！我们一定是这家咖啡店里最爱管闲事的人。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',1,'Officer','Good afternoon. License, please. Sir, you were going seventy-five.','警官：下午好。请出示驾照。先生，您刚才时速七十五。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',2,'Victor','Seventy-five?! That can''t be right! This car can''t even go that fast!','维克多：七十五？！这不可能对！我这车根本跑不了那么快！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',3,'Officer','The radar says it can.','警官：雷达说它可以。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',4,'Victor','Officer, there must be a mistake. Maybe the radar caught that red sports car!','维克多：警官，这一定是搞错了。也许雷达测到的是那辆红色跑车！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',5,'Officer','Hmm. A red sports car?','警官：嗯？红色跑车？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',6,'Victor','Yes! It passed me like I was standing still!','维克多：对！它超我的时候，我就跟静止了一样！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',7,'Officer','...Actually, you can''t be wrong. My partner just stopped a red sports car up the road.','警官：……还真是，你不可能说错。我搭档刚在前面拦下一辆红色跑车。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',8,'Victor','See! It must be that guy!','维克多：看吧！一定是那家伙！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',9,'Officer','You''re free to go, sir. But hey—your left light is out. You have to fix it this week.','警官：您可以走了，先生。不过——您左边车灯坏了，这周得修好。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',10,'Victor','Of course it is. Sir, I must be the unluckiest driver in this town.','维克多：果然又坏了。警官，我一定是全城最倒霉的司机。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',11,'Officer','Ha! Drive safe.','警官：哈哈！注意行车安全。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l65',12,'Victor','Always. Well... mostly.','维克多：一向如此。呃……大部分时候。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',1,'Dana','Wendy! Still on for the picnic Saturday?','达娜：温蒂！周六野餐还照旧吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',2,'Wendy','Maybe... The weather app says it might rain.','温蒂：不好说……天气 App 说可能下雨。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',3,'Dana','Might? Or will?','达娜：可能？还是一定？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',4,'Wendy','Sixty percent. So it may rain, or it may not. Classic spring.','温蒂：百分之六十。可能下，也可能不下。典型的春天。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',5,'Dana','Okay, plan B. We might move it to Sunday.','达娜：好，B 计划。我们也许挪到周日。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',6,'Wendy','Sunday works for me. But my sister may come too—is that okay?','温蒂：周日我可以。不过我妹妹可能也来——没问题吧？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',7,'Dana','Of course! The more, the merrier.','达娜：当然！人越多越热闹。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',8,'Wendy','Ha! She might bring her famous lemon bars.','温蒂：哈哈！她可能会带她的招牌柠檬方块。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',9,'Dana','Then she HAS to come. No "might" about it!','达娜：那她必须来。没有"可能"这一说！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',10,'Wendy','Ha! Okay. And if it rains on Sunday too?','温蒂：哈哈！好。那要是周日也下雨呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',11,'Dana','Then we may just have a picnic in my living room. Blanket and all!','达娜：那我们就干脆在我家客厅野餐。连毯子都铺上！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l66',12,'Wendy','It''s a plan. Rain or shine!','温蒂：就这么定了。风雨无阻！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',1,'Ken','Lauren! Did you see the news? Marcus Cole is retiring!','肯：劳伦！看新闻了吗？马库斯·科尔要退役了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',2,'Lauren','The quarterback? No way! What did he say?','劳伦：那个四分卫？不会吧！他说什么了？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',3,'Ken','He said that twenty years was enough.','肯：他说二十年够了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',4,'Lauren','Wow. Twenty years. What else?','劳伦：哇，整整二十年。还说什么了？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',5,'Ken','He said he wants more time with his kids.','肯：他说他想多陪陪孩子。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',6,'Lauren','Aww. That''s sweet. And his plans?','劳伦：太暖了。那他有什么打算？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',7,'Ken','He said that he might open a pizza place.','肯：他说他可能开一家披萨店。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',8,'Lauren','A pizza place?! I love that. What did his coach say?','劳伦：披萨店？！我爱了。他教练怎么说？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',9,'Ken','The coach said Marcus was the hardest worker on the team.','肯：教练说马库斯是队里最拼的人。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',10,'Lauren','True. My dad always said, "Watch number 12—he never quits."','劳伦：确实。我爸总说："盯住 12 号——他从不放弃。"') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',11,'Ken','Ha! Well, number 12 said thank you and goodbye.','肯：哈哈！现在，12 号说了声谢谢和再见。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l67',12,'Lauren','End of an era. Okay—pizza place field trip when it opens?','劳伦：一个时代结束了。好——店开业了咱们组团去？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',1,'Priya','Megan! Big Maplewood news. Did you hear?','普丽娅：梅根！枫木镇大新闻。你听说了吗？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',2,'Megan','No! Tell me everything.','梅根：没有！快全告诉我。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',3,'Priya','Ruth told me that the bookstore is moving to Main Street!','普丽娅：露丝跟我说，书店要搬到主街上了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',4,'Megan','The bookstore?! That''s huge. Who told you?','梅根：书店？！这可是大事。谁跟你说的？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',5,'Priya','Ruth herself. And she told me they will have a coffee corner.','普丽娅：露丝本人。她还跟我说店里会开个咖啡角。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',6,'Megan','Books AND coffee? Take my money.','梅根：书加咖啡？快收下我的钱。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',7,'Priya','Ha! Also—Carlos told me that the block party is moving to the new trail.','普丽娅：哈哈！还有——卡洛斯跟我说，街区派对要挪到新步道那边办了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',8,'Megan','The new trail by the river? Perfect.','梅根：河边那条新步道？完美。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',9,'Priya','Yep. And Jonas told everybody that he will bring pizza from Tony''s.','普丽娅：对。乔纳斯还跟大家说，他会从托尼家带披萨来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',10,'Megan','This town, honestly. Everybody knows everything in two hours.','梅根：这镇子啊，说真的。任何事两小时内人尽皆知。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',11,'Priya','Ha! Don''t say that—YOU told ME about the Hendersons'' dog!','普丽娅：哈哈！你可别这么说——亨德森家狗的事就是你告诉我的！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l68',12,'Megan','...Fair. See you at the trail!','梅根：……有道理。步道见！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',1,'Ryan','Zoe, look—the jackpot is 400 million!','瑞安：佐伊，你看——头奖四个亿！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',2,'Zoe','Whoa. Okay, two tickets. If we win, we''ll split it fifty-fifty.','佐伊：哇哦。行，买两张。要是中了，咱们五五分。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',3,'Ryan','Deal. So—what will you do if you win?','瑞安：成交。那——要是你中了，你打算干什么？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',4,'Zoe','Easy. If I win, I''ll quit my job... politely.','佐伊：简单。中了我就辞职……礼貌地辞。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',5,'Ryan','Ha! And then?','瑞安：哈哈！然后呢？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',6,'Zoe','I''ll buy a beach house. And if my sister asks, I''ll buy her one too.','佐伊：买栋海景房。要是我妹开口，也给她买一栋。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',7,'Ryan','Generous! If I win, I''ll travel for a whole year.','瑞安：大方！要是我中了，我要旅行整整一年。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',8,'Zoe','Where will you go first?','佐伊：先去哪儿？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',9,'Ryan','Japan. And if the money is still there after that, Italy.','瑞安：日本。之后钱要是还没花完，就去意大利。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',10,'Zoe','Smart. Okay, real talk: if we don''t win, we''ll still get tacos tonight?','佐伊：明智。好，说正经的：要是没中，今晚照样吃塔可吧？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',11,'Ryan','Obviously. Win or lose, taco night is taco night.','瑞安：那当然。无论输赢，塔可之夜就是塔可之夜。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l69',12,'Zoe','That''s why we''re friends.','佐伊：所以咱俩才是朋友。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',1,'Gloria','Lakeside Dental, this is Gloria.','格洛丽亚：湖畔牙科，我是格洛丽亚。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',2,'Bella','Hi! I''d like a large pepperoni pizza, extra cheese.','贝拉：你好！我要一份大份辣香肠披萨，加倍芝士。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',3,'Gloria','Ma''am... this is a dental office.','格洛丽亚：女士……这里是牙科诊所。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',4,'Bella','Oh no. I''m so sorry! Wrong number!','贝拉：天哪。太抱歉了！打错了！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',5,'Gloria','Ha! No worries. It happens every week—we''re one digit from Tony''s Pizza.','格洛丽亚：哈哈！没关系。每周都有——我们和托尼披萨就差一位数。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',6,'Bella','Wait, really? That''s hilarious.','贝拉：等等，真的？太好笑了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',7,'Gloria','Yep. Actually, while you''re here—may I ask, when was your last cleaning?','格洛丽亚：真的。话说，既然您都打来了——冒昧问一句，您上次洗牙是什么时候？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',8,'Bella','My last...? Oh. Um. Two years ago?','贝拉：上次……？呃。嗯。两年前？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',9,'Gloria','Mm-hmm. Can I schedule you for Tuesday? Dr. Kim has an opening.','格洛丽亚：嗯哼。我给您约周二好吗？金医生正好有空档。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',10,'Bella','You know what? Sure. Book it. Best wrong number ever.','贝拉：您猜怎么着？行。就这么订。史上最佳打错电话。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',11,'Gloria','Perfect! I''ll tell Dr. Kim that you''re coming. And Bella—Tony''s is 555-0198.','格洛丽亚：完美！我会告诉金医生您要来。对了贝拉——托尼家的号码是 555-0198。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l70',12,'Bella','Ha! You''re the best. Pizza first, teeth Tuesday!','贝拉：哈哈！你最棒了。今晚披萨，周二看牙！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',1,'Dorothy','First flight, sweetie? Your hands are shaking a little.','多萝西：第一次坐飞机吧，孩子？你的手有点抖。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',2,'Hailey','Is it that obvious? Yes. Before today, I had never been on a plane.','海莉：这么明显吗？是的。在今天之前，我从没坐过飞机。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',3,'Dorothy','Aww. Where are you headed?','多萝西：真可爱。你这是去哪儿？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',4,'Hailey','Westfield College! Move-in day is tomorrow.','海莉：韦斯特菲尔德学院！明天就是入住报到日。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',5,'Dorothy','College! How exciting. You know, I had never flown before my fortieth birthday.','多萝西：上大学！多让人激动。你知道吗，我四十岁生日之前从没坐过飞机。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',6,'Hailey','Really? Never?','海莉：真的？从没有？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',7,'Dorothy','Never. I had lived in the same small town my whole life. Then one day, I bought a ticket to Paris.','多萝西：从没有。我一辈子都住在同一个小镇。然后有一天，我买了张去巴黎的机票。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',8,'Hailey','Paris?! Just like that?','海莉：巴黎？！说走就走？') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',9,'Dorothy','Just like that. By the time I came home, I had visited nine countries.','多萝西：说走就走。等我回到家的时候，我已经去过九个国家了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',10,'Hailey','Whoa. That''s the dream.','海莉：哇哦。这就是梦想生活。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',11,'Dorothy','So don''t be nervous, sweetie. Every big life starts with one scary first step.','多萝西：所以别紧张，孩子。每一段精彩人生，都始于一次令人害怕的第一步。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l71',12,'Hailey','...Okay. Okay! First flight, here we go.','海莉：……好。好！第一次飞行，出发！') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',1,NULL,'On the first Saturday of June, Maplewood opened its new river trail.','六月的第一个周六，枫木镇的新河滨步道正式启用。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',2,NULL,'Everybody who lived in town came to the party.','镇上的每一个人都来参加了庆祝派对。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',3,NULL,'Carlos and Megan had planned the day for months, and it was perfect.','卡洛斯和梅根为这一天筹备了好几个月，一切完美。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',4,NULL,'Jonas brought pizza from Tony''s, and Megan''s lemonade went fast—as always.','乔纳斯从托尼家带来了披萨，梅根的柠檬水一如既往地被抢光。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',5,NULL,'Rosa and Nina were guessing everybody''s story by the coffee stand.','罗莎和妮娜在咖啡摊边玩着"猜人生"的游戏。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',6,NULL,'"That runner must be training for a race," Rosa said.','"那个跑步的人一定在备赛，"罗莎说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',7,NULL,'She was right—it was Molly, who has run three 5Ks since spring.','她猜对了——那是莫莉，开春以来她已经跑完了三个五公里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',8,NULL,'Victor arrived late, of course. "My car didn''t start," he told everybody. Nobody was surprised.','维克多照例迟到了。"我的车没打着火，"他跟大家说。没有人感到意外。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',9,NULL,'Kyle and Andre told the raccoon story again, and it got funnier every time.','凯尔和安德烈又讲了一遍浣熊的故事，每讲一次都更好笑。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',10,NULL,'"If the weather stays nice, we''ll do this every month," Carlos said.','"如果天气一直这么好，我们每个月都办一次，"卡洛斯说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',11,NULL,'Hailey, home from college, took photos of everything. "I had never seen the whole town in one place," she said.','从大学回家的海莉拍下了一切。"我从没见过全镇的人聚在同一个地方，"她说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am1_l72',12,NULL,'The sun went down slowly over the river. Maplewood had never looked better.','夕阳缓缓沉入河面。枫木镇从没这么美过。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
