INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l65_gp1','am1_l65','can''t be 否定推测','**① can''t be（否定推测"不可能是"）**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l65_gp2','am1_l65','must be / can''t be 对照','**① can''t be（否定推测"不可能是"）**
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am1_l66_gp1','am1_l66','may / might 不确定推测','**① may / might + 动词原形（可能——不确定的推测）**
